const {execSync}=require('child_process');
const files={
  'frontend/src/app/(public)/kiro/page.tsx': "\"use client\";\nimport { useState, useRef, useEffect, useCallback } from \"react\";\nimport { motion, AnimatePresence } from \"framer-motion\";\nimport Link from \"next/link\";\nimport dynamic from \"next/dynamic\";\nimport { useAuthStore } from \"../../../store/auth.store\";\n\nconst BASE    = process.env.NEXT_PUBLIC_API_URL || \"https://dropos-v2.onrender.com/api\";\nconst ACCENT  = \"#7C3AED\";\nconst ACCENT_D = \"#5B21B6\";\n\nconst KIROChatFull = dynamic(() => import(\"../../../components/kai/KIROChat\"), {\n  ssr: false, loading: () => <Loader />,\n});\n\nconst TL = {\n  bg:\"#F7F6F3\",s1:\"#FFFFFF\",s2:\"#EFEEEA\",s3:\"#E5E4DF\",\n  text:\"#111827\",sub:\"#6B7280\",muted:\"#9CA3AF\",\n  border:\"rgba(0,0,0,0.08)\",borderH:\"rgba(0,0,0,0.18)\",\n  accent:ACCENT,accentD:ACCENT_D,accentBg:ACCENT+\"12\",\n  shadow:\"0 1px 4px rgba(0,0,0,0.06),0 4px 20px rgba(0,0,0,0.04)\",\n  green:\"#059669\",amber:\"#D97706\",red:\"#DC2626\",\n};\nconst TD = {\n  bg:\"#0D0D14\",s1:\"#13131F\",s2:\"#1A1A2A\",s3:\"#232338\",\n  text:\"#F9F8FF\",sub:\"#A0A0C0\",muted:\"#606080\",\n  border:\"rgba(255,255,255,0.07)\",borderH:\"rgba(255,255,255,0.16)\",\n  accent:\"#9061F9\",accentD:ACCENT,accentBg:ACCENT+\"18\",\n  shadow:\"0 1px 4px rgba(0,0,0,0.4)\",\n  green:\"#10B981\",amber:\"#F59E0B\",red:\"#EF4444\",\n};\n\nconst FONTS = `\n@import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700&display=swap');\n@keyframes spin{to{transform:rotate(360deg)}}\n@keyframes kping{0%,100%{transform:scale(1);opacity:.5}60%{transform:scale(2.4);opacity:0}}\n@keyframes fadeUp{from{opacity:0;transform:translateY(8px)}to{opacity:1;transform:none}}\n@keyframes voicePulse{0%,100%{transform:scaleY(1)}50%{transform:scaleY(1.8)}}\n*{box-sizing:border-box}\n::-webkit-scrollbar{width:3px}\n::-webkit-scrollbar-thumb{background:rgba(124,58,237,0.2);border-radius:2px}\n::selection{background:rgba(124,58,237,0.18)}\n`;\n\n// ── History ────────────────────────────────────────────────────\ninterface Session { id: string; title: string; ts: number; }\nfunction genId() { return Math.random().toString(36).slice(2,10); }\nfunction timeAgo(ts: number) {\n  const d = (Date.now()-ts)/1000;\n  if (d<60) return \"just now\";\n  if (d<3600) return Math.floor(d/60)+\"m ago\";\n  if (d<86400) return Math.floor(d/3600)+\"h ago\";\n  return Math.floor(d/86400)+\"d ago\";\n}\nfunction loadHist(): Session[] {\n  try { return JSON.parse(localStorage.getItem(\"kiro_hist\")||\"[]\"); } catch { return []; }\n}\nfunction pushHist(id: string, title: string) {\n  const h = loadHist().filter(x=>x.id!==id);\n  h.unshift({ id, title: title.slice(0,54), ts: Date.now() });\n  localStorage.setItem(\"kiro_hist\", JSON.stringify(h.slice(0,20)));\n}\nfunction delHist(id: string) {\n  localStorage.setItem(\"kiro_hist\", JSON.stringify(loadHist().filter(x=>x.id!==id)));\n}\n\n// ── Primitives ─────────────────────────────────────────────────\nfunction Loader() {\n  return (\n    <div style={{flex:1,display:\"flex\",alignItems:\"center\",justifyContent:\"center\",background:\"#F7F6F3\"}}>\n      <div style={{width:24,height:24,borderRadius:\"50%\",border:`2px solid ${ACCENT}30`,borderTopColor:ACCENT,animation:\"spin 0.8s linear infinite\"}}/>\n    </div>\n  );\n}\n\nfunction Logo({ size=28 }: { size?: number }) {\n  return (\n    <div style={{width:size,height:size,borderRadius:Math.round(size*.27),background:`linear-gradient(145deg,${ACCENT},${ACCENT_D})`,display:\"flex\",alignItems:\"center\",justifyContent:\"center\",flexShrink:0,boxShadow:`0 2px 8px ${ACCENT}40`}}>\n      <svg width={size*.44} height={size*.44} viewBox=\"0 0 24 24\" fill=\"none\">\n        <path d=\"M13 2L3 14h9l-1 8 10-12h-9z\" fill=\"white\" fillOpacity={.95}/>\n      </svg>\n    </div>\n  );\n}\n\nfunction PulseDot() {\n  return (\n    <span style={{position:\"relative\",display:\"inline-flex\",width:8,height:8,flexShrink:0}}>\n      <span style={{position:\"absolute\",inset:0,borderRadius:\"50%\",background:\"#10B981\",animation:\"kping 1.6s ease-in-out infinite\"}}/>\n      <span style={{width:8,height:8,borderRadius:\"50%\",background:\"#10B981\",position:\"relative\"}}/>\n    </span>\n  );\n}\n\nfunction ModeBtn({ mode, toggle, T }: { mode:\"light\"|\"dark\"; toggle:()=>void; T:typeof TL }) {\n  return (\n    <button onClick={toggle}\n      style={{width:32,height:32,borderRadius:8,border:`1px solid ${T.border}`,background:\"transparent\",cursor:\"pointer\",display:\"flex\",alignItems:\"center\",justifyContent:\"center\",fontSize:14,flexShrink:0}}\n      onMouseEnter={e=>(e.currentTarget.style.background=T.accentBg)}\n      onMouseLeave={e=>(e.currentTarget.style.background=\"transparent\")}>\n      {mode===\"light\"?\"🌙\":\"☀️\"}\n    </button>\n  );\n}\n\n// ── Voice input ────────────────────────────────────────────────\nfunction VoiceBtn({ onTranscript, T }: { onTranscript:(t:string)=>void; T:typeof TL }) {\n  const [state, setState] = useState<\"idle\"|\"recording\"|\"processing\">(\"idle\");\n  const [interim, setInterim] = useState(\"\");\n  const recogRef = useRef<any>(null);\n\n  function start() {\n    const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;\n    if (!SpeechRecognition) { alert(\"Voice not supported in this browser\"); return; }\n    const r = new SpeechRecognition();\n    r.continuous = true;\n    r.interimResults = true;\n    r.lang = \"en-NG\";\n    r.onstart = () => setState(\"recording\");\n    r.onresult = (e: any) => {\n      let interim = \"\", final = \"\";\n      for (let i = e.resultIndex; i < e.results.length; i++) {\n        const t = e.results[i][0].transcript;\n        if (e.results[i].isFinal) final += t;\n        else interim += t;\n      }\n      setInterim(interim);\n      if (final) { onTranscript(final); stop(); }\n    };\n    r.onerror = () => stop();\n    r.onend   = () => setState(\"idle\");\n    recogRef.current = r;\n    r.start();\n  }\n\n  function stop() {\n    recogRef.current?.stop();\n    setState(\"idle\");\n    setInterim(\"\");\n  }\n\n  const isRec = state === \"recording\";\n\n  return (\n    <div style={{position:\"relative\",display:\"flex\",alignItems:\"center\",gap:6}}>\n      {/* live transcript bubble */}\n      <AnimatePresence>\n        {isRec && interim && (\n          <motion.div initial={{opacity:0,y:4,scale:.96}} animate={{opacity:1,y:0,scale:1}} exit={{opacity:0}}\n            style={{position:\"absolute\",bottom:\"calc(100% + 8px)\",right:0,background:T.s1,border:`1px solid ${T.border}`,borderRadius:10,padding:\"7px 12px\",fontSize:12,color:T.text,whiteSpace:\"nowrap\",maxWidth:220,overflow:\"hidden\",textOverflow:\"ellipsis\",boxShadow:T.shadow,zIndex:10}}>\n            <span style={{color:T.muted,fontSize:10,display:\"block\",marginBottom:2}}>Listening…</span>\n            {interim}\n          </motion.div>\n        )}\n      </AnimatePresence>\n\n      {/* recording bars */}\n      {isRec && (\n        <div style={{display:\"flex\",alignItems:\"center\",gap:2}}>\n          {[0,1,2,3,4].map(i=>(\n            <div key={i} style={{width:3,height:14,borderRadius:99,background:ACCENT,animation:`voicePulse 0.6s ease-in-out ${i*0.1}s infinite`}}/>\n          ))}\n        </div>\n      )}\n\n      <button\n        onClick={isRec ? stop : start}\n        title={isRec ? \"Stop recording\" : \"Voice input\"}\n        style={{width:30,height:30,borderRadius:8,border:`1px solid ${isRec?\"#EF4444\":T.border}`,background:isRec?\"rgba(239,68,68,0.1)\":\"transparent\",cursor:\"pointer\",display:\"flex\",alignItems:\"center\",justifyContent:\"center\",flexShrink:0,transition:\"all 0.2s\"}}>\n        {isRec\n          ? <svg width=\"12\" height=\"12\" viewBox=\"0 0 24 24\" fill=\"#EF4444\"><rect x=\"4\" y=\"4\" width=\"16\" height=\"16\" rx=\"2\"/></svg>\n          : <svg width=\"13\" height=\"13\" viewBox=\"0 0 24 24\" fill=\"none\" stroke={T.sub} strokeWidth=\"2\" strokeLinecap=\"round\">\n              <path d=\"M12 1a3 3 0 0 0-3 3v8a3 3 0 0 0 6 0V4a3 3 0 0 0-3-3z\"/>\n              <path d=\"M19 10v2a7 7 0 0 1-14 0v-2\"/>\n              <line x1=\"12\" y1=\"19\" x2=\"12\" y2=\"23\"/>\n              <line x1=\"8\"  y1=\"23\" x2=\"16\" y2=\"23\"/>\n            </svg>\n        }\n      </button>\n    </div>\n  );\n}\n\n// ── Auth dropdown ──────────────────────────────────────────────\nfunction AuthDropdown({ T, onLogin, onLoggedOut }: { T:typeof TL; onLogin:()=>void; onLoggedOut:()=>void }) {\n  const { user, logout } = useAuthStore();\n  const [open, setOpen]  = useState(false);\n  const ref = useRef<HTMLDivElement>(null);\n\n  useEffect(() => {\n    const h = (e: MouseEvent) => { if (ref.current && !ref.current.contains(e.target as Node)) setOpen(false); };\n    document.addEventListener(\"mousedown\", h);\n    return () => document.removeEventListener(\"mousedown\", h);\n  }, []);\n\n  async function handleLogout() {\n    setOpen(false);\n    try { await logout(); } catch {}\n    [\"kiro_sid\",\"accessToken\",\"dropos-refresh-token\"].forEach(k => localStorage.removeItem(k));\n    onLoggedOut(); // <-- returns to guest view\n  }\n\n  if (!user) {\n    return (\n      <button onClick={onLogin}\n        style={{padding:\"6px 16px\",borderRadius:8,border:\"none\",background:`linear-gradient(135deg,${ACCENT},${ACCENT_D})`,color:\"#fff\",fontSize:13,fontWeight:600,cursor:\"pointer\",fontFamily:\"inherit\",whiteSpace:\"nowrap\",boxShadow:`0 2px 10px ${ACCENT}30`}}>\n        Get started free\n      </button>\n    );\n  }\n\n  const initials = (user.name||user.email||\"U\").slice(0,2).toUpperCase();\n  const first    = user.name?.split(\" \")[0] || user.email?.split(\"@\")[0] || \"User\";\n\n  return (\n    <div ref={ref} style={{position:\"relative\",flexShrink:0}}>\n      <button onClick={() => setOpen(o=>!o)}\n        style={{display:\"flex\",alignItems:\"center\",gap:7,padding:\"4px 10px 4px 4px\",borderRadius:9,border:`1px solid ${T.border}`,background:T.s2,cursor:\"pointer\",fontFamily:\"inherit\",flexShrink:0,transition:\"border-color .15s\"}}\n        onMouseEnter={e=>(e.currentTarget.style.borderColor=T.borderH)}\n        onMouseLeave={e=>(e.currentTarget.style.borderColor=T.border)}>\n        <div style={{width:28,height:28,borderRadius:8,background:`linear-gradient(135deg,${ACCENT},${ACCENT_D})`,display:\"flex\",alignItems:\"center\",justifyContent:\"center\",fontSize:11,fontWeight:800,color:\"#fff\",flexShrink:0}}>{initials}</div>\n        <span style={{fontSize:12,fontWeight:600,color:T.text,maxWidth:72,overflow:\"hidden\",textOverflow:\"ellipsis\",whiteSpace:\"nowrap\"}}>{first}</span>\n        <svg width=\"10\" height=\"10\" viewBox=\"0 0 24 24\" fill=\"none\" stroke={T.muted} strokeWidth=\"2.5\" strokeLinecap=\"round\"><path d=\"M6 9l6 6 6-6\"/></svg>\n      </button>\n\n      <AnimatePresence>\n        {open && (\n          <motion.div initial={{opacity:0,y:5,scale:.96}} animate={{opacity:1,y:0,scale:1}} exit={{opacity:0,y:4,scale:.96}} transition={{duration:.13}}\n            style={{position:\"absolute\",right:0,top:\"calc(100% + 7px)\",minWidth:185,borderRadius:13,background:T.s1,border:`1px solid ${T.border}`,boxShadow:\"0 10px 36px rgba(0,0,0,0.16)\",overflow:\"hidden\",zIndex:300}}>\n            <div style={{padding:\"11px 14px\",borderBottom:`1px solid ${T.border}`}}>\n              <p style={{fontSize:12,fontWeight:700,color:T.text}}>{user.name||\"User\"}</p>\n              <p style={{fontSize:11,color:T.muted,marginTop:1}}>{user.email}</p>\n            </div>\n            <Link href=\"/dashboard\" style={{textDecoration:\"none\"}}>\n              <button style={{width:\"100%\",padding:\"10px 14px\",display:\"flex\",alignItems:\"center\",gap:9,background:\"none\",border:\"none\",cursor:\"pointer\",textAlign:\"left\",fontFamily:\"inherit\",transition:\"background .12s\"}}\n                onMouseEnter={e=>(e.currentTarget.style.background=T.accentBg)}\n                onMouseLeave={e=>(e.currentTarget.style.background=\"none\")}>\n                <svg width=\"13\" height=\"13\" viewBox=\"0 0 24 24\" fill=\"none\" stroke={T.accent} strokeWidth=\"2\" strokeLinecap=\"round\"><rect x=\"3\" y=\"3\" width=\"7\" height=\"7\" rx=\"1\"/><rect x=\"14\" y=\"3\" width=\"7\" height=\"7\" rx=\"1\"/><rect x=\"14\" y=\"14\" width=\"7\" height=\"7\" rx=\"1\"/><rect x=\"3\" y=\"14\" width=\"7\" height=\"7\" rx=\"1\"/></svg>\n                <span style={{fontSize:13,fontWeight:600,color:T.text}}>Dashboard</span>\n              </button>\n            </Link>\n            <button onClick={handleLogout}\n              style={{width:\"100%\",padding:\"10px 14px\",display:\"flex\",alignItems:\"center\",gap:9,background:\"none\",border:\"none\",borderTop:`1px solid ${T.border}`,cursor:\"pointer\",textAlign:\"left\",fontFamily:\"inherit\",transition:\"background .12s\"}}\n              onMouseEnter={e=>(e.currentTarget.style.background=\"rgba(220,38,38,.07)\")}\n              onMouseLeave={e=>(e.currentTarget.style.background=\"none\")}>\n              <svg width=\"13\" height=\"13\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#DC2626\" strokeWidth=\"2\" strokeLinecap=\"round\"><path d=\"M9 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h4\"/><polyline points=\"16 17 21 12 16 7\"/><line x1=\"21\" y1=\"12\" x2=\"9\" y2=\"12\"/></svg>\n              <span style={{fontSize:13,fontWeight:600,color:\"#DC2626\"}}>Log out</span>\n            </button>\n          </motion.div>\n        )}\n      </AnimatePresence>\n    </div>\n  );\n}\n\n// ── History sidebar ────────────────────────────────────────────\nfunction Sidebar({ history, activeId, onSelect, onNew, onDelete, open, onClose, T }:\n  { history:Session[]; activeId:string; onSelect:(id:string)=>void; onNew:()=>void; onDelete:(id:string)=>void; open:boolean; onClose:()=>void; T:typeof TL }) {\n  return (\n    <>\n      <AnimatePresence>\n        {open && (\n          <motion.div initial={{opacity:0}} animate={{opacity:1}} exit={{opacity:0}}\n            style={{position:\"fixed\",inset:0,background:\"rgba(0,0,0,0.3)\",zIndex:90,backdropFilter:\"blur(2px)\"}}\n            onClick={onClose}/>\n        )}\n      </AnimatePresence>\n      <motion.div animate={{x:open?0:-280}} initial={{x:-280}} transition={{type:\"spring\",stiffness:340,damping:34}}\n        style={{position:\"fixed\",left:0,top:0,bottom:0,width:260,background:T.s1,borderRight:`1px solid ${T.border}`,zIndex:100,display:\"flex\",flexDirection:\"column\",boxShadow:\"4px 0 24px rgba(0,0,0,0.1)\"}}>\n\n        <div style={{padding:\"13px 14px\",borderBottom:`1px solid ${T.border}`,display:\"flex\",alignItems:\"center\",justifyContent:\"space-between\",flexShrink:0}}>\n          <div style={{display:\"flex\",alignItems:\"center\",gap:8}}><Logo size={22}/><span style={{fontSize:13,fontWeight:700,color:T.text}}>Chat history</span></div>\n          <button onClick={onClose}\n            style={{width:26,height:26,borderRadius:6,border:`1px solid ${T.border}`,background:\"transparent\",cursor:\"pointer\",display:\"flex\",alignItems:\"center\",justifyContent:\"center\",color:T.muted}}\n            onMouseEnter={e=>(e.currentTarget.style.background=T.s2)} onMouseLeave={e=>(e.currentTarget.style.background=\"transparent\")}>\n            <svg width=\"11\" height=\"11\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" strokeWidth=\"2.5\" strokeLinecap=\"round\"><path d=\"M18 6L6 18M6 6l12 12\"/></svg>\n          </button>\n        </div>\n\n        <div style={{padding:\"10px 10px 6px\",flexShrink:0}}>\n          <button onClick={onNew}\n            style={{width:\"100%\",padding:\"8px 0\",borderRadius:9,border:`1.5px dashed ${T.borderH}`,background:T.accentBg,color:T.accent,fontWeight:600,fontSize:12,cursor:\"pointer\",display:\"flex\",alignItems:\"center\",gap:7,justifyContent:\"center\",fontFamily:\"inherit\",transition:\"opacity .15s\"}}\n            onMouseEnter={e=>(e.currentTarget.style.opacity=\"0.75\")} onMouseLeave={e=>(e.currentTarget.style.opacity=\"1\")}>\n            <svg width=\"12\" height=\"12\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" strokeWidth=\"2.5\" strokeLinecap=\"round\"><path d=\"M12 5v14M5 12h14\"/></svg>\n            New chat\n          </button>\n        </div>\n\n        <div style={{flex:1,overflowY:\"auto\",padding:\"4px 8px 16px\"}}>\n          {history.length===0 && (\n            <div style={{textAlign:\"center\",marginTop:32,padding:\"0 12px\"}}>\n              <div style={{fontSize:24,marginBottom:8}}>💬</div>\n              <p style={{fontSize:12,color:T.muted,lineHeight:1.7}}>No chats yet.<br/>Start a conversation<br/>and it'll appear here.</p>\n            </div>\n          )}\n          {history.map(s => (\n            <div key={s.id}\n              onClick={() => onSelect(s.id)}\n              style={{display:\"flex\",alignItems:\"center\",gap:7,padding:\"8px 10px\",borderRadius:9,marginBottom:2,background:s.id===activeId?T.accentBg:\"transparent\",cursor:\"pointer\",transition:\"background .14s\",position:\"relative\",group:\"true\"}}\n              onMouseEnter={e => {\n                if (s.id!==activeId)(e.currentTarget as HTMLElement).style.background=T.s2;\n                const btn = e.currentTarget.querySelector(\".del-btn\") as HTMLElement;\n                if (btn) btn.style.opacity=\"1\";\n              }}\n              onMouseLeave={e => {\n                if (s.id!==activeId)(e.currentTarget as HTMLElement).style.background=\"transparent\";\n                const btn = e.currentTarget.querySelector(\".del-btn\") as HTMLElement;\n                if (btn) btn.style.opacity=\"0\";\n              }}>\n              <svg width=\"12\" height=\"12\" viewBox=\"0 0 24 24\" fill=\"none\" stroke={s.id===activeId?T.accent:T.muted} strokeWidth=\"2\" strokeLinecap=\"round\" style={{flexShrink:0}}>\n                <path d=\"M21 15a2 2 0 0 1-2 2H7l-4 4V5a2 2 0 0 1 2-2h14a2 2 0 0 1 2 2z\"/>\n              </svg>\n              <div style={{flex:1,minWidth:0}}>\n                <p style={{fontSize:12,fontWeight:600,color:s.id===activeId?T.accent:T.text,overflow:\"hidden\",textOverflow:\"ellipsis\",whiteSpace:\"nowrap\"}}>{s.title||\"New conversation\"}</p>\n                <p style={{fontSize:10,color:T.muted,marginTop:1}}>{timeAgo(s.ts)}</p>\n              </div>\n              <button\n                className=\"del-btn\"\n                onClick={e => { e.stopPropagation(); onDelete(s.id); }}\n                style={{flexShrink:0,width:18,height:18,borderRadius:5,border:\"none\",background:\"rgba(220,38,38,.12)\",color:\"#DC2626\",cursor:\"pointer\",display:\"flex\",alignItems:\"center\",justifyContent:\"center\",opacity:0,transition:\"opacity .15s\"}}>\n                <svg width=\"8\" height=\"8\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" strokeWidth=\"2.5\" strokeLinecap=\"round\"><path d=\"M18 6L6 18M6 6l12 12\"/></svg>\n              </button>\n            </div>\n          ))}\n        </div>\n      </motion.div>\n    </>\n  );\n}\n\n// ── Auth modal ─────────────────────────────────────────────────\nfunction AuthModal({ onClose, onSuccess, T }: { onClose:()=>void; onSuccess:(sid:string)=>void; T:typeof TL }) {\n  const [tab, setTab]   = useState<\"register\"|\"login\">(\"register\");\n  const [name, setName] = useState(\"\"); const [email, setEmail] = useState(\"\"); const [pass, setPass] = useState(\"\");\n  const [err, setErr]   = useState(\"\"); const [busy, setBusy]   = useState(false);\n  const inp: React.CSSProperties = { width:\"100%\",padding:\"10px 14px\",borderRadius:9,border:`1px solid ${T.border}`,background:T.s2,color:T.text,fontSize:14,fontFamily:\"'Inter',sans-serif\",outline:\"none\",transition:\"border-color 0.15s,box-shadow 0.15s\" };\n  const focus = (e: React.FocusEvent<HTMLInputElement>) => { e.currentTarget.style.borderColor=ACCENT; e.currentTarget.style.boxShadow=`0 0 0 3px ${ACCENT}15`; };\n  const blur  = (e: React.FocusEvent<HTMLInputElement>, T: typeof TL) => { e.currentTarget.style.borderColor=T.border; e.currentTarget.style.boxShadow=\"none\"; };\n\n  async function submit() {\n    if (!email||!pass) return; setBusy(true); setErr(\"\");\n    try {\n      const body = tab===\"register\" ? {name,email,password:pass} : {email,password:pass};\n      const res  = await fetch(`${BASE}/auth/${tab}`,{method:\"POST\",headers:{\"Content-Type\":\"application/json\"},body:JSON.stringify(body)});\n      const d    = await res.json();\n      if (!res.ok) { setErr(d.message||\"Something went wrong\"); setBusy(false); return; }\n      const { accessToken, refreshToken:rt, user } = d.data||{};\n      if (rt) localStorage.setItem(\"dropos-refresh-token\", rt);\n      if (accessToken) {\n        try {\n          const { useAuthStore } = await import(\"../../../store/auth.store\");\n          useAuthStore.getState().setUser(user);\n          useAuthStore.getState().setAccessToken(accessToken);\n        } catch {}\n        onSuccess(user?.stores?.[0]?.id||\"\");\n      }\n    } catch { setErr(\"Connection error\"); } finally { setBusy(false); }\n  }\n\n  return (\n    <div style={{position:\"fixed\",inset:0,zIndex:500,display:\"flex\",alignItems:\"center\",justifyContent:\"center\",padding:16,background:\"rgba(0,0,0,0.45)\",backdropFilter:\"blur(10px)\"}}\n      onClick={e=>e.target===e.currentTarget&&onClose()}>\n      <motion.div initial={{opacity:0,y:10,scale:.97}} animate={{opacity:1,y:0,scale:1}} transition={{type:\"spring\",stiffness:320,damping:28}}\n        style={{width:\"100%\",maxWidth:350,borderRadius:18,background:T.s1,border:`1px solid ${T.border}`,padding:\"26px 22px\",boxShadow:\"0 24px 60px rgba(0,0,0,0.2)\"}}>\n        <div style={{textAlign:\"center\",marginBottom:20}}>\n          <div style={{display:\"flex\",justifyContent:\"center\",marginBottom:12}}><Logo size={38}/></div>\n          <h2 style={{fontSize:19,fontWeight:700,color:T.text,margin:\"0 0 4px\",letterSpacing:\"-0.3px\"}}>{tab===\"register\"?\"Create account\":\"Welcome back\"}</h2>\n          <p style={{fontSize:12,color:T.muted}}>{tab===\"register\"?\"Free · No card needed\":\"Sign in to KIRO\"}</p>\n        </div>\n        <div style={{display:\"flex\",gap:2,padding:3,borderRadius:9,background:T.s2,marginBottom:16}}>\n          {([\"register\",\"login\"] as const).map(m=>(\n            <button key={m} onClick={()=>{setTab(m);setErr(\"\");}}\n              style={{flex:1,padding:\"6px\",borderRadius:7,border:\"none\",cursor:\"pointer\",fontFamily:\"'Inter',sans-serif\",fontSize:12,fontWeight:500,transition:\"all 0.15s\",background:tab===m?T.s1:\"transparent\",color:tab===m?T.text:T.muted,boxShadow:tab===m?T.shadow:\"none\"}}>\n              {m===\"register\"?\"Sign up\":\"Sign in\"}\n            </button>\n          ))}\n        </div>\n        <div style={{display:\"flex\",flexDirection:\"column\",gap:9}}>\n          {tab===\"register\"&&<input value={name} onChange={e=>setName(e.target.value)} placeholder=\"Full name\" autoFocus style={inp} onFocus={focus} onBlur={e=>blur(e,T)}/>}\n          <input value={email} onChange={e=>setEmail(e.target.value)} placeholder=\"Email\" type=\"email\" autoFocus={tab===\"login\"} style={inp} onFocus={focus} onBlur={e=>blur(e,T)}/>\n          <input value={pass}  onChange={e=>setPass(e.target.value)}  placeholder=\"Password\" type=\"password\" style={inp} onFocus={focus} onBlur={e=>blur(e,T)} onKeyDown={e=>e.key===\"Enter\"&&submit()}/>\n          {err && <p style={{fontSize:12,color:\"#DC2626\",textAlign:\"center\",margin:0}}>{err}</p>}\n          <button onClick={submit} disabled={busy||!email||!pass}\n            style={{padding:\"11px\",borderRadius:9,border:\"none\",cursor:busy||!email||!pass?\"not-allowed\":\"pointer\",fontFamily:\"'Inter',sans-serif\",fontSize:14,fontWeight:600,marginTop:2,background:busy||!email||!pass?T.s3:`linear-gradient(135deg,${ACCENT},${ACCENT_D})`,color:busy||!email||!pass?T.muted:\"#fff\",transition:\"all 0.2s\",boxShadow:!busy&&email&&pass?`0 4px 14px ${ACCENT}30`:\"none\"}}>\n            {busy?\"…\":tab===\"register\"?\"Create account →\":\"Sign in →\"}\n          </button>\n        </div>\n      </motion.div>\n    </div>\n  );\n}\n\n// ── Demo chat (guest) ──────────────────────────────────────────\ntype Msg = { id:string; role:\"user\"|\"ai\"; text:string; streaming?:boolean };\nconst STARTERS = [\"What can KIRO do?\",\"I sell fashion in Lagos\",\"Find trending products\",\"How to import from AliExpress?\"];\n\nfunction DemoChat({ T, onAuthNeeded }: { T:typeof TL; onAuthNeeded:()=>void }) {\n  const [msgs,    setMsgs]    = useState<Msg[]>([{id:\"0\",role:\"ai\",text:\"I'm KIRO — your AI business partner. I help African dropshippers source products, write ads, fulfill orders, and understand their market. What do you sell?\"}]);\n  const [input,   setInput]   = useState(\"\");\n  const [loading, setLoading] = useState(false);\n  const [count,   setCount]   = useState(0);\n  const endRef = useRef<HTMLDivElement>(null);\n  const taRef  = useRef<HTMLTextAreaElement>(null);\n\n  useEffect(() => { endRef.current?.scrollIntoView({behavior:\"smooth\"}); }, [msgs]);\n\n  const send = useCallback(async (text?: string) => {\n    const msg = (text||input).trim(); if (!msg||loading) return;\n    setInput(\"\"); if (taRef.current) taRef.current.style.height=\"auto\";\n    const n = count+1; setCount(n);\n    if (n>=5) { setMsgs(p=>[...p,{id:`u${Date.now()}`,role:\"user\",text:msg}]); setTimeout(onAuthNeeded,200); return; }\n    const kid = `k${Date.now()}`;\n    setMsgs(p=>[...p,{id:`u${Date.now()}`,role:\"user\",text:msg},{id:kid,role:\"ai\",text:\"\",streaming:true}]);\n    setLoading(true);\n    try {\n      const res = await fetch(`${BASE}/kai/public-chat`,{method:\"POST\",headers:{\"Content-Type\":\"application/json\"},body:JSON.stringify({message:msg})});\n      if (!res.ok||!res.body) throw new Error();\n      const reader = res.body.getReader(); const dec = new TextDecoder(); let full=\"\";\n      while (true) {\n        const {done,value}=await reader.read(); if (done) break;\n        for (const line of dec.decode(value,{stream:true}).split(\"\\n\")) {\n          if (!line.startsWith(\"data: \")) continue;\n          try { const p=JSON.parse(line.slice(6)); if(p.token){full+=p.token;setMsgs(m=>m.map(x=>x.id===kid?{...x,text:full}:x));endRef.current?.scrollIntoView({behavior:\"smooth\"});} } catch {}\n        }\n      }\n      setMsgs(m=>m.map(x=>x.id===kid?{...x,streaming:false,text:full||\"Create a free account to unlock the full KIRO experience.\"}:x));\n    } catch {\n      setMsgs(m=>m.map(x=>x.id===kid?{...x,streaming:false,text:\"Create a free account to get started with KIRO.\"}:x));\n    } finally { setLoading(false); }\n  }, [input,loading,count,onAuthNeeded]);\n\n  return (\n    <div style={{display:\"flex\",flexDirection:\"column\",height:\"100%\",minHeight:0}}>\n      <div style={{flex:1,overflowY:\"auto\",padding:\"16px 16px 8px\",minHeight:0}}>\n        {msgs.map(msg=>(\n          <motion.div key={msg.id} initial={{opacity:0,y:5}} animate={{opacity:1,y:0}} transition={{duration:0.2}}\n            style={{display:\"flex\",flexDirection:msg.role===\"user\"?\"row-reverse\":\"row\",gap:7,alignItems:\"flex-end\",marginBottom:12}}>\n            {msg.role===\"ai\"&&<Logo size={22}/>}\n            <div style={{maxWidth:\"82%\",padding:msg.role===\"user\"?\"9px 14px\":\"0\",borderRadius:msg.role===\"user\"?\"16px 16px 4px 16px\":\"0\",background:msg.role===\"user\"?`linear-gradient(145deg,${ACCENT},${ACCENT_D})`:\"transparent\",color:msg.role===\"user\"?\"#fff\":T.text,fontSize:14,lineHeight:1.68,boxShadow:msg.role===\"user\"?`0 2px 8px ${ACCENT}28`:\"none\"}}>\n              {msg.streaming&&!msg.text\n                ? <div style={{display:\"flex\",gap:4,padding:\"3px 0\"}}>{[0,1,2].map(i=><motion.div key={i} style={{width:5,height:5,borderRadius:\"50%\",background:T.muted}} animate={{y:[0,-4,0],opacity:[0.4,1,0.4]}} transition={{duration:0.6,repeat:Infinity,delay:i*0.12}}/>)}</div>\n                : <span>{msg.text}{msg.streaming&&<motion.span animate={{opacity:[1,0]}} transition={{duration:0.5,repeat:Infinity}} style={{display:\"inline-block\",width:2,height:13,background:T.muted,marginLeft:1,verticalAlign:\"text-bottom\"}}/>}</span>\n              }\n            </div>\n          </motion.div>\n        ))}\n        {count>=2&&(\n          <motion.div initial={{opacity:0,y:6}} animate={{opacity:1,y:0}}\n            style={{margin:\"4px 0 10px\",padding:\"12px 14px\",borderRadius:11,background:T.accentBg,border:`1px solid ${T.border}`}}>\n            <p style={{fontSize:13,fontWeight:600,color:T.text,margin:\"0 0 3px\"}}>KIRO is better with your store</p>\n            <p style={{fontSize:12,color:T.muted,margin:\"0 0 8px\"}}>Free account unlocks full product import, analytics, and AI actions.</p>\n            <button onClick={onAuthNeeded} style={{padding:\"6px 14px\",borderRadius:7,border:\"none\",background:`linear-gradient(135deg,${ACCENT},${ACCENT_D})`,color:\"#fff\",fontSize:12,fontWeight:600,cursor:\"pointer\",fontFamily:\"'Inter',sans-serif\"}}>Start free →</button>\n          </motion.div>\n        )}\n        <div ref={endRef}/>\n      </div>\n      {msgs.length<=1&&(\n        <div style={{padding:\"0 16px 8px\",display:\"flex\",gap:6,flexWrap:\"wrap\"}}>\n          {STARTERS.map(s=>(\n            <button key={s} onClick={()=>send(s)}\n              style={{padding:\"5px 11px\",borderRadius:99,border:`1px solid ${T.border}`,background:\"transparent\",color:T.sub,fontSize:12,cursor:\"pointer\",fontFamily:\"'Inter',sans-serif\",transition:\"all 0.15s\",whiteSpace:\"nowrap\"}}\n              onMouseEnter={e=>{e.currentTarget.style.borderColor=T.borderH;e.currentTarget.style.color=T.text;}}\n              onMouseLeave={e=>{e.currentTarget.style.borderColor=T.border;e.currentTarget.style.color=T.sub;}}>\n              {s}\n            </button>\n          ))}\n        </div>\n      )}\n      <div style={{padding:\"8px 14px 14px\",flexShrink:0}}>\n        <div style={{display:\"flex\",gap:8,alignItems:\"flex-end\",borderRadius:12,border:`1px solid ${T.border}`,background:T.s1,padding:\"7px 9px\",boxShadow:T.shadow,transition:\"border-color 0.15s\"}}\n          onFocusCapture={e=>(e.currentTarget as HTMLDivElement).style.borderColor=ACCENT}\n          onBlurCapture={e=>(e.currentTarget as HTMLDivElement).style.borderColor=T.border}>\n          <textarea ref={taRef} value={input}\n            onChange={e=>{setInput(e.target.value);e.target.style.height=\"auto\";e.target.style.height=Math.min(e.target.scrollHeight,90)+\"px\";}}\n            onKeyDown={e=>{if(e.key===\"Enter\"&&!e.shiftKey){e.preventDefault();send();}}}\n            placeholder=\"Ask KIRO anything…\" rows={1}\n            style={{flex:1,background:\"transparent\",border:\"none\",outline:\"none\",color:T.text,fontSize:14,fontFamily:\"'Inter',sans-serif\",lineHeight:1.5,resize:\"none\",maxHeight:90,overflowY:\"auto\",padding:\"2px 0\"}}/>\n          <VoiceBtn T={T} onTranscript={t=>{setInput(p=>p?p+\" \"+t:t);}}/>\n          <motion.button onClick={()=>send()} whileTap={{scale:.88}} disabled={loading||!input.trim()}\n            style={{width:28,height:28,borderRadius:8,border:\"none\",cursor:input.trim()&&!loading?\"pointer\":\"not-allowed\",display:\"flex\",alignItems:\"center\",justifyContent:\"center\",flexShrink:0,transition:\"all 0.18s\",background:input.trim()&&!loading?`linear-gradient(135deg,${ACCENT},${ACCENT_D})`:T.s3,opacity:input.trim()&&!loading?1:0.45}}>\n            {loading\n              ? <div style={{width:11,height:11,borderRadius:\"50%\",border:`2px solid ${ACCENT}30`,borderTopColor:ACCENT,animation:\"spin 0.7s linear infinite\"}}/>\n              : <svg width={11} height={11} viewBox=\"0 0 24 24\" fill=\"none\"><path d=\"M22 2L11 13M22 2L15 22l-4-9-9-4 20-7z\" stroke=\"white\" strokeWidth={2} strokeLinecap=\"round\" strokeLinejoin=\"round\"/></svg>\n            }\n          </motion.button>\n        </div>\n      </div>\n    </div>\n  );\n}\n\n// ── Auto-login helper ──────────────────────────────────────────\nasync function tryAutoLogin() {\n  if (typeof window===\"undefined\") return null;\n  const r = localStorage.getItem(\"dropos-refresh-token\"); if (!r) return null;\n  try {\n    const res = await fetch(`${BASE}/auth/refresh`,{method:\"POST\",headers:{\"Content-Type\":\"application/json\"},body:JSON.stringify({refreshToken:r})});\n    if (!res.ok) return null;\n    const {data} = await res.json(); if (!data?.accessToken) return null;\n    if (data.refreshToken) localStorage.setItem(\"dropos-refresh-token\", data.refreshToken);\n    try {\n      const {useAuthStore} = await import(\"../../../store/auth.store\");\n      useAuthStore.getState().setUser(data.user);\n      useAuthStore.getState().setAccessToken(data.accessToken);\n    } catch {}\n    return { storeId: data.user?.stores?.[0]?.id||\"\" };\n  } catch { return null; }\n}\n\nconst CAPS = [\n  {icon:\"🌐\",text:\"Import from any website\"},\n  {icon:\"📊\",text:\"Live store analytics\"},\n  {icon:\"⚡\",text:\"Actions from chat\"},\n  {icon:\"🔥\",text:\"Market intelligence\"},\n  {icon:\"📣\",text:\"AI ad copy\"},\n  {icon:\"🎯\",text:\"Goals & pulse alerts\"},\n];\n\n// ── Main ───────────────────────────────────────────────────────\nexport default function KIROPage() {\n  const { user } = useAuthStore();\n  const [authState, setAuthState] = useState<\"checking\"|\"authed\"|\"guest\">(\"checking\");\n  const [storeId,   setStoreId]   = useState(\"\");\n  const [showAuth,  setShowAuth]  = useState(false);\n  const [mode,      setMode]      = useState<\"light\"|\"dark\">(\"light\");\n  const [history,   setHistory]   = useState<Session[]>([]);\n  const [sessionId, setSessionId] = useState(\"\");\n  const [sidebarOpen, setSidebarOpen] = useState(false);\n  const firstMsgRef = useRef<string>(\"\");\n  const T = mode===\"light\" ? TL : TD;\n\n  // History helpers\n  const refreshHist = useCallback(() => setHistory(loadHist()), []);\n  const newSession  = useCallback(() => {\n    const id = genId();\n    setSessionId(id);\n    setSidebarOpen(false);\n    refreshHist();\n  }, [refreshHist]);\n  const pickSession = useCallback((id: string) => {\n    setSessionId(id);\n    setSidebarOpen(false);\n  }, []);\n  const removeSession = useCallback((id: string) => {\n    delHist(id);\n    refreshHist();\n    if (id===sessionId) newSession();\n  }, [sessionId, newSession, refreshHist]);\n\n  // Record a chat when user sends their first message\n  const recordChat = useCallback((firstMsg: string) => {\n    if (sessionId) { pushHist(sessionId, firstMsg); refreshHist(); }\n  }, [sessionId, refreshHist]);\n\n  useEffect(() => {\n    const saved = localStorage.getItem(\"kiro-mode\") as \"light\"|\"dark\"|null;\n    if (saved) setMode(saved);\n    const id = genId(); setSessionId(id);\n    refreshHist();\n    tryAutoLogin().then(r => {\n      if (r) { setStoreId(r.storeId); setAuthState(\"authed\"); }\n      else setAuthState(\"guest\");\n    });\n  }, []);\n\n  const toggleMode = () => {\n    const n = mode===\"light\"?\"dark\":\"light\";\n    setMode(n); localStorage.setItem(\"kiro-mode\",n);\n  };\n\n  // ── Logged in: auth success\n  const handleAuth = (sid: string) => {\n    setStoreId(sid); setAuthState(\"authed\"); setShowAuth(false);\n    const id = genId(); setSessionId(id); refreshHist();\n  };\n\n  // ── Logout: go back to guest\n  const handleLogout = () => {\n    setAuthState(\"guest\");\n    setSessionId(genId());\n    setSidebarOpen(false);\n  };\n\n  // ── Checking splash\n  if (authState===\"checking\") return (\n    <div style={{height:\"100dvh\",display:\"flex\",alignItems:\"center\",justifyContent:\"center\",background:TL.bg}}>\n      <style>{FONTS}</style>\n      <div style={{width:26,height:26,borderRadius:\"50%\",border:`2px solid ${ACCENT}30`,borderTopColor:ACCENT,animation:\"spin 0.8s linear infinite\"}}/>\n    </div>\n  );\n\n  // ── Authed: full chat\n  if (authState===\"authed\") return (\n    <div style={{height:\"100dvh\",display:\"flex\",flexDirection:\"column\",background:T.bg,overflow:\"hidden\",fontFamily:\"'Inter',sans-serif\"}}>\n      <style>{FONTS+`body,html{background:${T.bg}}`}</style>\n\n      <Sidebar\n        history={history} activeId={sessionId}\n        onSelect={pickSession} onNew={newSession} onDelete={removeSession}\n        open={sidebarOpen} onClose={()=>setSidebarOpen(false)} T={T}/>\n\n      <header style={{height:48,display:\"flex\",alignItems:\"center\",justifyContent:\"space-between\",padding:\"0 16px\",borderBottom:`1px solid ${T.border}`,background:T.s1,flexShrink:0,boxShadow:T.shadow,gap:10}}>\n        <div style={{display:\"flex\",alignItems:\"center\",gap:8,minWidth:0}}>\n          <button onClick={()=>setSidebarOpen(o=>!o)}\n            style={{width:30,height:30,borderRadius:7,border:`1px solid ${T.border}`,background:\"transparent\",cursor:\"pointer\",display:\"flex\",alignItems:\"center\",justifyContent:\"center\",color:T.sub,flexShrink:0,transition:\"background .15s\"}}\n            onMouseEnter={e=>(e.currentTarget.style.background=T.s2)}\n            onMouseLeave={e=>(e.currentTarget.style.background=\"transparent\")}>\n            <svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" strokeWidth=\"2\" strokeLinecap=\"round\"><path d=\"M3 12h18M3 6h18M3 18h18\"/></svg>\n          </button>\n          <Logo size={24}/>\n          <span style={{fontSize:14,fontWeight:700,color:T.text,flexShrink:0}}>KIRO</span>\n          <PulseDot/>\n          {/* current session title */}\n          {history.find(h=>h.id===sessionId) && (\n            <span style={{fontSize:11,color:T.muted,overflow:\"hidden\",textOverflow:\"ellipsis\",whiteSpace:\"nowrap\",maxWidth:160}}>\n              {history.find(h=>h.id===sessionId)?.title}\n            </span>\n          )}\n        </div>\n        <div style={{display:\"flex\",gap:8,alignItems:\"center\",flexShrink:0}}>\n          <ModeBtn mode={mode} toggle={toggleMode} T={T}/>\n          <AuthDropdown T={T} onLogin={()=>setShowAuth(true)} onLoggedOut={handleLogout}/>\n        </div>\n      </header>\n\n      {/* key={sessionId} forces full remount on new chat */}\n      <div style={{flex:1,overflow:\"hidden\",minHeight:0}} key={sessionId}>\n        <KIROChatFull\n          storeId={storeId}\n          conversationId={history.find(h=>h.id===sessionId)?.id === sessionId && sessionId.length > 8 ? sessionId : undefined}\n          onFirstMessage={(text) => { firstMsgRef.current = text; }}\n          onConversationCreated={(convId) => {\n            const title = firstMsgRef.current || \"KIRO conversation\";\n            pushHist(convId, title);\n            setSessionId(convId);\n            refreshHist();\n          }}\n        />\n      </div>\n\n      {showAuth && <AuthModal T={T} onClose={()=>setShowAuth(false)} onSuccess={handleAuth}/>}\n    </div>\n  );\n\n  // ── Guest: marketing + demo\n  return (\n    <div style={{height:\"100dvh\",display:\"flex\",flexDirection:\"column\",background:T.bg,overflow:\"hidden\",fontFamily:\"'Inter',sans-serif\",transition:\"background 0.25s\"}}>\n      <style>{FONTS+`body,html{background:${T.bg}}`}</style>\n      {showAuth && <AuthModal T={T} onClose={()=>setShowAuth(false)} onSuccess={handleAuth}/>}\n\n      <nav style={{height:52,display:\"flex\",alignItems:\"center\",padding:\"0 20px\",borderBottom:`1px solid ${T.border}`,background:T.s1,flexShrink:0,boxShadow:T.shadow,gap:8}}>\n        <div style={{display:\"flex\",alignItems:\"center\",gap:8,flex:1,minWidth:0}}>\n          <Logo size={26}/>\n          <span style={{fontSize:15,fontWeight:700,color:T.text,flexShrink:0}}>KIRO</span>\n          <span style={{fontSize:9,padding:\"2px 6px\",borderRadius:4,background:T.accentBg,color:T.accent,fontWeight:700,letterSpacing:\"0.07em\",textTransform:\"uppercase\",border:`1px solid ${T.border}`,flexShrink:0}}>Beta</span>\n        </div>\n        <div style={{display:\"flex\",gap:8,alignItems:\"center\",flexShrink:0}}>\n          <ModeBtn mode={mode} toggle={toggleMode} T={T}/>\n          <button onClick={()=>setShowAuth(true)}\n            style={{padding:\"6px 14px\",borderRadius:8,border:`1px solid ${T.border}`,background:\"transparent\",color:T.sub,fontSize:13,fontWeight:500,cursor:\"pointer\",fontFamily:\"'Inter',sans-serif\",transition:\"all 0.15s\",whiteSpace:\"nowrap\"}}\n            onMouseEnter={e=>{e.currentTarget.style.borderColor=T.borderH;e.currentTarget.style.color=T.text;}}\n            onMouseLeave={e=>{e.currentTarget.style.borderColor=T.border;e.currentTarget.style.color=T.sub;}}>Sign in</button>\n          <button onClick={()=>setShowAuth(true)}\n            style={{padding:\"6px 16px\",borderRadius:8,border:\"none\",background:`linear-gradient(135deg,${ACCENT},${ACCENT_D})`,color:\"#fff\",fontSize:13,fontWeight:600,cursor:\"pointer\",fontFamily:\"'Inter',sans-serif\",whiteSpace:\"nowrap\",boxShadow:`0 2px 10px ${ACCENT}30`}}>\n            Get started free\n          </button>\n        </div>\n      </nav>\n\n      <div style={{flex:1,display:\"grid\",gridTemplateColumns:\"360px 1fr\",minHeight:0,overflow:\"hidden\"}} className=\"kiro-grid\">\n        <div style={{borderRight:`1px solid ${T.border}`,display:\"flex\",flexDirection:\"column\",justifyContent:\"space-between\",padding:\"32px 24px\",overflow:\"hidden\"}} className=\"kiro-left\">\n          <div>\n            <motion.div initial={{opacity:0,y:10}} animate={{opacity:1,y:0}} transition={{delay:.05}}>\n              <p style={{fontSize:10,fontWeight:700,color:T.muted,letterSpacing:\"0.1em\",textTransform:\"uppercase\",marginBottom:10}}>For African dropshippers</p>\n              <h1 style={{fontSize:30,fontWeight:700,color:T.text,lineHeight:1.18,letterSpacing:\"-0.5px\",marginBottom:12}}>Your AI<br/>commerce<br/>partner.</h1>\n              <p style={{fontSize:14,color:T.sub,lineHeight:1.7,marginBottom:24,maxWidth:270}}>Import products, write ad copy, manage orders, and understand your market — all from one conversation.</p>\n            </motion.div>\n            <div style={{display:\"flex\",flexDirection:\"column\",gap:6}}>\n              {CAPS.map((c,i)=>(\n                <motion.div key={c.text} initial={{opacity:0,x:-8}} animate={{opacity:1,x:0}} transition={{delay:.15+i*.05}}\n                  style={{display:\"flex\",alignItems:\"center\",gap:9,padding:\"8px 10px\",borderRadius:9,background:T.s1,border:`1px solid ${T.border}`}}>\n                  <span style={{fontSize:14,flexShrink:0}}>{c.icon}</span>\n                  <span style={{fontSize:12,fontWeight:500,color:T.text}}>{c.text}</span>\n                </motion.div>\n              ))}\n            </div>\n          </div>\n          <motion.div initial={{opacity:0}} animate={{opacity:1}} transition={{delay:.5}}\n            style={{padding:\"13px 14px\",borderRadius:11,background:T.s1,border:`1px solid ${T.border}`,marginTop:20}}>\n            <p style={{fontSize:13,color:T.sub,lineHeight:1.6,fontStyle:\"italic\",marginBottom:6}}>\"KIRO found me 3 winning products and wrote all my TikTok scripts. First ₦100k month done.\"</p>\n            <p style={{fontSize:11,color:T.muted,fontWeight:600}}>Adaeze O. · Lagos, Nigeria</p>\n          </motion.div>\n        </div>\n\n        <div style={{display:\"flex\",flexDirection:\"column\",minHeight:0,overflow:\"hidden\"}}>\n          <div style={{height:42,display:\"flex\",alignItems:\"center\",justifyContent:\"space-between\",padding:\"0 18px\",borderBottom:`1px solid ${T.border}`,flexShrink:0}}>\n            <div style={{display:\"flex\",alignItems:\"center\",gap:6}}>\n              <div style={{width:6,height:6,borderRadius:\"50%\",background:T.green,boxShadow:`0 0 6px ${T.green}`}}/>\n              <span style={{fontSize:12,fontWeight:500,color:T.sub}}>Live demo</span>\n            </div>\n            <button onClick={()=>setShowAuth(true)}\n              style={{fontSize:12,fontWeight:600,color:T.accent,background:\"transparent\",border:\"none\",cursor:\"pointer\",fontFamily:\"'Inter',sans-serif\",padding:\"3px 8px\",borderRadius:5,transition:\"background 0.15s\"}}\n              onMouseEnter={e=>(e.currentTarget.style.background=T.accentBg)}\n              onMouseLeave={e=>(e.currentTarget.style.background=\"transparent\")}>\n              Get full access →\n            </button>\n          </div>\n          <div style={{flex:1,minHeight:0,overflow:\"hidden\"}}>\n            <DemoChat T={T} onAuthNeeded={()=>setShowAuth(true)}/>\n          </div>\n        </div>\n      </div>\n\n      <style>{`@media(max-width:660px){.kiro-grid{grid-template-columns:1fr!important}.kiro-left{display:none!important}}`}</style>\n    </div>\n  );\n}\n",
  'frontend/src/components/kai/KIROChat.tsx': "\"use client\";\n/**\n * KIROChat — DropOS Commerce AI\n * Fresh build. No legacy. Clean design system.\n *\n * DESIGN: \"Warm Precision\"\n * Light default: Linen #F7F6F3 → Ink #111827, Violet #7C3AED accent\n * Dark:          Obsidian #0D0D14 → Snow #F9F8FF, same accent\n * Font: Geist (display) + Inter (body) — loaded from CDN\n *\n * LAYOUT: Column flex, height:100%, minHeight:0 everywhere.\n * No absolute positioning in the main flow.\n * KIRO_ACTION: buffered server-side, stripped client-side.\n */\n\nimport React, { useState, useRef, useEffect, useCallback } from \"react\";\nimport { motion, AnimatePresence } from \"framer-motion\";\nimport { useAuthStore } from \"../../store/auth.store\";\nimport { api, uploadAPI } from \"../../lib/api\";\nimport toast from \"react-hot-toast\";\n\n// ── constants ──────────────────────────────────────────────────────────────────\nconst BASE   = process.env.NEXT_PUBLIC_API_URL || \"https://dropos-v2.onrender.com/api\";\nconst ACCENT = \"#7C3AED\";\nconst ACCENT_D = \"#5B21B6\";\n\n// ── types ──────────────────────────────────────────────────────────────────────\ntype Mode = \"light\" | \"dark\";\ninterface Msg {\n  id:         string;\n  role:       \"user\" | \"assistant\";\n  content:    string;\n  streaming?: boolean;\n  imageUrl?:  string;\n  actions?:   Action[];\n  ts?:        string;\n  thumbs?:    \"up\" | \"down\";\n}\ninterface Action {\n  type:     string;\n  payload:  Record<string,unknown>;\n  approved?: boolean;\n}\n\n// ── theme tokens ───────────────────────────────────────────────────────────────\nconst T = {\n  light: {\n    bg:       \"#F7F6F3\",\n    surface:  \"#FFFFFF\",\n    elevated: \"#F0EFE9\",\n    border:   \"rgba(0,0,0,0.08)\",\n    borderFocus: ACCENT + \"60\",\n    text:     \"#111827\",\n    sub:      \"#6B7280\",\n    muted:    \"#9CA3AF\",\n    accent:   ACCENT,\n    accentD:  ACCENT_D,\n    accentBg: ACCENT + \"12\",\n    userBg:   `linear-gradient(145deg, ${ACCENT}, ${ACCENT_D})`,\n    userText: \"#ffffff\",\n    shadow:   \"0 1px 4px rgba(0,0,0,0.06), 0 4px 20px rgba(0,0,0,0.04)\",\n    shadowMd: \"0 4px 24px rgba(0,0,0,0.10)\",\n    green:    \"#059669\",\n    amber:    \"#D97706\",\n    red:      \"#DC2626\",\n    scrollbar: \"rgba(0,0,0,0.12)\",\n  },\n  dark: {\n    bg:       \"#0D0D14\",\n    surface:  \"#13131F\",\n    elevated: \"#1A1A2A\",\n    border:   \"rgba(255,255,255,0.07)\",\n    borderFocus: ACCENT + \"70\",\n    text:     \"#F9F8FF\",\n    sub:      \"#A0A0C0\",\n    muted:    \"#606080\",\n    accent:   \"#9061F9\",\n    accentD:  ACCENT,\n    accentBg: ACCENT + \"18\",\n    userBg:   `linear-gradient(145deg, ${ACCENT}, ${ACCENT_D})`,\n    userText: \"#ffffff\",\n    shadow:   \"0 1px 4px rgba(0,0,0,0.4)\",\n    shadowMd: \"0 4px 24px rgba(0,0,0,0.5)\",\n    green:    \"#10B981\",\n    amber:    \"#F59E0B\",\n    red:      \"#F87171\",\n    scrollbar: \"rgba(255,255,255,0.1)\",\n  },\n};\n\n// ── clean KIRO_ACTION from text ────────────────────────────────────────────────\nfunction cleanText(raw: string): string {\n  if (!raw) return \"\";\n  let result = \"\";\n  let i = 0;\n  while (i < raw.length) {\n    const markerIdx = raw.indexOf(\"KIRO_ACTION\", i);\n    if (markerIdx === -1) { result += raw.slice(i); break; }\n    result += raw.slice(i, markerIdx);\n    let j = markerIdx + 11;\n    while (j < raw.length && /[\\s:`]/.test(raw[j])) j++;\n    if (j < raw.length && raw[j] === \"{\") {\n      let depth = 0;\n      while (j < raw.length) {\n        if (raw[j] === \"{\") depth++;\n        else if (raw[j] === \"}\") { depth--; if (depth === 0) { j++; break; } }\n        j++;\n      }\n      while (j < raw.length && (raw[j] === \"\\n\" || raw[j] === \"`\" || raw[j] === \" \")) j++;\n    }\n    i = j;\n  }\n  return result\n    .replace(/```json[\\s\\S]*?```/gi, \"\")\n    .replace(/```[\\s\\S]*?```/g, \"\")\n    .replace(/\\*\\*([^*]+)\\*\\*/g, \"$1\")\n    .replace(/\\*([^*\\n]+)\\*/g, \"$1\")\n    .replace(/^#{1,6}\\s/gm, \"\")\n    .replace(/━+/g, \"\").replace(/^[-=]{3,}\\s*$/gm, \"\")\n    .replace(/\\n{3,}/g, \"\\n\\n\").trim();\n}\n\n// ── parse actions from text ────────────────────────────────────────────────────\nfunction parseActions(text: string): Action[] {\n  const actions: Action[] = [];\n  const re = /KIRO_ACTION\\s*:?\\s*/g;\n  let match: RegExpExecArray | null;\n  while ((match = re.exec(text)) !== null) {\n    const start = text.indexOf(\"{\", match.index + match[0].length);\n    if (start === -1) continue;\n    let depth = 0, j = start;\n    while (j < text.length) {\n      if (text[j] === \"{\") depth++;\n      else if (text[j] === \"}\") { depth--; if (depth === 0) { j++; break; } }\n      j++;\n    }\n    try {\n      const obj = JSON.parse(text.slice(start, j));\n      if (obj.type) actions.push({ type: obj.type, payload: obj.payload || obj });\n    } catch {}\n  }\n  return actions;\n}\n\n// ── action card labels ─────────────────────────────────────────────────────────\nconst ACTION_META: Record<string, { icon: string; label: string; cta: string }> = {\n  add_product:           { icon:\"📦\", label:\"Add product\",         cta:\"Add to store\"    },\n  import_from_url:       { icon:\"🌐\", label:\"Import product\",      cta:\"Import\"          },\n  update_price:          { icon:\"💰\", label:\"Update price\",        cta:\"Update\"          },\n  update_stock:          { icon:\"📋\", label:\"Update stock\",        cta:\"Update\"          },\n  create_coupon:         { icon:\"🎟\", label:\"Create coupon\",       cta:\"Create\"          },\n  create_coupon_v2:      { icon:\"🎟\", label:\"Create coupon\",       cta:\"Create\"          },\n  fulfill_order:         { icon:\"🚚\", label:\"Fulfill order\",       cta:\"Fulfill\"         },\n  update_order_status:   { icon:\"📬\", label:\"Update order\",        cta:\"Update\"          },\n  create_flash_sale:     { icon:\"⚡\", label:\"Flash sale\",          cta:\"Launch\"          },\n  archive_product:       { icon:\"🔒\", label:\"Archive product\",     cta:\"Archive\"         },\n  delete_product:        { icon:\"🗑\", label:\"Delete product\",      cta:\"Delete\"          },\n  duplicate_product:     { icon:\"📋\", label:\"Duplicate product\",   cta:\"Duplicate\"       },\n  add_tracking:          { icon:\"📦\", label:\"Add tracking\",        cta:\"Add\"             },\n  process_refund:        { icon:\"💸\", label:\"Process refund\",      cta:\"Refund\"          },\n  send_email:            { icon:\"📧\", label:\"Send email\",          cta:\"Send\"            },\n  send_whatsapp:         { icon:\"💬\", label:\"Send WhatsApp\",       cta:\"Send\"            },\n  bulk_update_prices:    { icon:\"💰\", label:\"Bulk price update\",   cta:\"Update all\"      },\n  update_store_description:{ icon:\"✏️\", label:\"Update store\",     cta:\"Update\"          },\n  update_product:        { icon:\"✏️\", label:\"Update product\",      cta:\"Save\"            },\n};\n\n// ── Time greeting ──────────────────────────────────────────────────────────────\nfunction getGreeting(name: string) {\n  const h = new Date().getHours();\n  const firstName = name.split(\" \")[0];\n  if (h < 5)  return `Still up, ${firstName}?`;\n  if (h < 12) return `Good morning, ${firstName}.`;\n  if (h < 17) return `Good afternoon, ${firstName}.`;\n  if (h < 21) return `Good evening, ${firstName}.`;\n  return `Late night, ${firstName}.`;\n}\n\n// ── KIRO Logo ──────────────────────────────────────────────────────────────────\nfunction KIROLogo({ size = 28 }: { size?: number }) {\n  return (\n    <div style={{\n      width: size, height: size, borderRadius: Math.round(size * 0.27),\n      background: `linear-gradient(145deg, ${ACCENT}, ${ACCENT_D})`,\n      display: \"flex\", alignItems: \"center\", justifyContent: \"center\", flexShrink: 0,\n      boxShadow: `0 2px 8px ${ACCENT}40`,\n    }}>\n      <svg width={size * 0.44} height={size * 0.44} viewBox=\"0 0 24 24\" fill=\"none\">\n        <path d=\"M13 2L3 14h9l-1 8 10-12h-9z\" fill=\"white\" fillOpacity={0.95}/>\n      </svg>\n    </div>\n  );\n}\n\n// ── Spinner ────────────────────────────────────────────────────────────────────\nfunction Spinner({ size = 16, color = ACCENT }: { size?: number; color?: string }) {\n  return <div style={{ width: size, height: size, borderRadius: \"50%\", border: `2px solid ${color}30`, borderTopColor: color, animation: \"ks 0.7s linear infinite\", flexShrink: 0 }}/>;\n}\n\n// ── Action card ────────────────────────────────────────────────────────────────\nfunction ActionCard({ action, onApprove, onDismiss, t }: { action: Action; onApprove:(a:Action)=>void; onDismiss:(a:Action)=>void; t: typeof T.light }) {\n  const [loading, setLoading] = useState(false);\n  const [done,    setDone]    = useState(false);\n  const meta = ACTION_META[action.type] || { icon:\"⚡\", label: action.type.replace(/_/g,\" \"), cta:\"Run\" };\n  if (done) return null;\n\n  const p = action.payload as any;\n  const summary = p?.name || p?.url?.slice(0,35) || p?.code || p?.trackingNumber || p?.message?.slice(0,40) || p?.status || \"\";\n\n  return (\n    <motion.div initial={{ opacity:0, y:4 }} animate={{ opacity:1, y:0 }}\n      style={{ marginTop: 10, borderRadius: 12, border: `1px solid ${t.border}`, background: t.surface, overflow: \"hidden\" }}>\n      <div style={{ padding: \"10px 14px 8px\", display: \"flex\", alignItems: \"flex-start\", gap: 8 }}>\n        <span style={{ fontSize: 18, flexShrink: 0, lineHeight: 1 }}>{meta.icon}</span>\n        <div style={{ flex: 1, minWidth: 0 }}>\n          <p style={{ fontSize: 12, fontWeight: 600, color: t.text, margin: 0 }}>{meta.label}</p>\n          {summary && <p style={{ fontSize: 11, color: t.sub, margin: \"2px 0 0\", overflow:\"hidden\", textOverflow:\"ellipsis\", whiteSpace:\"nowrap\" }}>{summary}</p>}\n        </div>\n      </div>\n      <div style={{ padding: \"0 14px 12px\", display: \"flex\", gap: 8 }}>\n        <button\n          onClick={async () => { setLoading(true); await onApprove(action); setDone(true); setLoading(false); }}\n          disabled={loading}\n          style={{ padding: \"6px 16px\", borderRadius: 8, border: \"none\", background: t.accent, color: \"#fff\", fontSize: 12, fontWeight: 600, cursor: \"pointer\", display: \"flex\", alignItems: \"center\", gap: 5 }}>\n          {loading ? <Spinner size={12} color=\"#fff\"/> : meta.cta}\n        </button>\n        <button onClick={() => { onDismiss(action); setDone(true); }}\n          style={{ padding: \"6px 12px\", borderRadius: 8, border: `1px solid ${t.border}`, background: \"transparent\", color: t.sub, fontSize: 12, cursor: \"pointer\" }}>\n          Dismiss\n        </button>\n      </div>\n    </motion.div>\n  );\n}\n\n// ── Message bubble ─────────────────────────────────────────────────────────────\nfunction MsgBubble({ msg, onApprove, onDismiss, onRate, onRegen, t }: {\n  msg: Msg; onApprove:(a:Action)=>void; onDismiss:(a:Action)=>void;\n  onRate:(id:string,v:\"up\"|\"down\")=>void; onRegen:(id:string)=>void; t: typeof T.light;\n}) {\n  const [show, setShow] = useState(false);\n  const isUser = msg.role === \"user\";\n  const text   = cleanText(msg.content || \"\");\n\n  return (\n    <motion.div\n      initial={{ opacity: 0, y: 6 }}\n      animate={{ opacity: 1, y: 0 }}\n      transition={{ duration: 0.2 }}\n      onMouseEnter={() => setShow(true)}\n      onMouseLeave={() => setShow(false)}\n      style={{ display: \"flex\", flexDirection: isUser ? \"row-reverse\" : \"row\", gap: 8, alignItems: \"flex-end\", marginBottom: 20, position: \"relative\" }}>\n\n      {!isUser && <KIROLogo size={26}/>}\n\n      <div style={{ maxWidth: \"80%\", minWidth: 0 }}>\n        {/* Image */}\n        {msg.imageUrl && (\n          <img src={msg.imageUrl} alt=\"\" style={{ maxWidth: \"100%\", maxHeight: 200, borderRadius: 10, marginBottom: 6, display: \"block\", objectFit: \"cover\" }} onError={e=>(e.currentTarget.style.display=\"none\")}/>\n        )}\n\n        {/* Text bubble */}\n        <div style={{\n          padding: isUser ? \"10px 15px\" : \"0\",\n          borderRadius: isUser ? \"18px 18px 4px 18px\" : \"0\",\n          background: isUser ? t.userBg : \"transparent\",\n          color: isUser ? t.userText : t.text,\n          fontSize: 14, lineHeight: 1.7,\n          boxShadow: isUser ? `0 2px 10px ${ACCENT}30` : \"none\",\n        }}>\n          {msg.streaming && !msg.content ? (\n            <div style={{ display:\"flex\", gap:4, alignItems:\"center\", padding:\"3px 0\" }}>\n              {[0,1,2].map(i=>(\n                <motion.div key={i} style={{ width:5, height:5, borderRadius:\"50%\", background: t.muted }}\n                  animate={{ y:[0,-4,0], opacity:[0.4,1,0.4] }}\n                  transition={{ duration:0.6, repeat:Infinity, delay:i*0.13 }}/>\n              ))}\n              <span style={{ fontSize:12, color: t.muted, marginLeft:6 }}>KIRO is thinking</span>\n            </div>\n          ) : (\n            <span style={{ whiteSpace: \"pre-wrap\", wordBreak: \"break-word\" }}>\n              {text}\n              {msg.streaming && <motion.span animate={{ opacity:[1,0] }} transition={{ duration:0.5, repeat:Infinity }} style={{ display:\"inline-block\", marginLeft:1 }}>▋</motion.span>}\n            </span>\n          )}\n\n          {/* Action cards */}\n          {!isUser && msg.actions?.map((a,i) => (\n            <ActionCard key={i} action={a} onApprove={onApprove} onDismiss={onDismiss} t={t}/>\n          ))}\n        </div>\n\n        {/* Toolbar */}\n        <AnimatePresence>\n          {show && !msg.streaming && (\n            <motion.div initial={{ opacity:0 }} animate={{ opacity:1 }} exit={{ opacity:0 }}\n              style={{ display:\"flex\", gap:3, marginTop:5, padding:\"0 2px\" }}>\n              {[\"📋\",\"👍\",\"👎\",\"↻\",\"🔊\"].map((icon, i) => (\n                <button key={i} title={[\"Copy\",\"Helpful\",\"Not helpful\",\"Retry\",\"Listen\"][i]}\n                  onClick={() => {\n                    if (i===0) navigator.clipboard.writeText(text);\n                    if (i===1) onRate(msg.id,\"up\");\n                    if (i===2) onRate(msg.id,\"down\");\n                    if (i===3) onRegen(msg.id);\n                    if (i===4) { const u = new SpeechSynthesisUtterance(text.slice(0,500)); u.lang=\"en-NG\"; window.speechSynthesis.speak(u); }\n                  }}\n                  style={{ width:24, height:24, borderRadius:6, border:`1px solid ${t.border}`, background: t.surface, color: t.sub, cursor:\"pointer\", fontSize:12, display:\"flex\", alignItems:\"center\", justifyContent:\"center\" }}>\n                  {icon}\n                </button>\n              ))}\n              {!isUser && (\n                <button title=\"Share to WhatsApp\"\n                  onClick={() => window.open(`https://wa.me/?text=${encodeURIComponent(text.slice(0,500))}`, \"_blank\")}\n                  style={{ width:24, height:24, borderRadius:6, border:`1px solid ${t.border}`, background: t.surface, color:\"#25D366\", cursor:\"pointer\", fontSize:12, display:\"flex\", alignItems:\"center\", justifyContent:\"center\" }}>\n                  📤\n                </button>\n              )}\n            </motion.div>\n          )}\n        </AnimatePresence>\n\n        {/* Timestamp */}\n        {msg.ts && !msg.streaming && (\n          <p style={{ fontSize:10, color: t.muted, margin:\"3px 0 0\", textAlign: isUser?\"right\":\"left\" }}>\n            {new Date(msg.ts).toLocaleTimeString([],{hour:\"2-digit\",minute:\"2-digit\"})}\n            {msg.thumbs && (msg.thumbs===\"up\"?\" · 👍\":\" · 👎\")}\n          </p>\n        )}\n      </div>\n    </motion.div>\n  );\n}\n\n// ── Welcome screen ─────────────────────────────────────────────────────────────\nfunction Welcome({ name, storeData, onSend, t }: { name:string; storeData:any; onSend:(m:string)=>void; t: typeof T.light }) {\n  const greeting = getGreeting(name || \"there\");\n  const sym      = storeData?.currencySymbol || \"₦\";\n\n  const QUICK = [\n    { icon:\"📊\", title:\"Store pulse\",       sub:\"Revenue · Health · What needs action\",  prompt:\"Give me my full store summary — revenue, orders, health score, and what I should focus on today.\" },\n    { icon:\"🔥\", title:\"Trending products\", sub:\"Live market research\",                   prompt:\"What products are trending right now in my market this week?\" },\n    { icon:\"🌐\", title:\"Import product\",    sub:\"Any URL — AliExpress, Temu, Amazon\",     prompt:\"I want to import a product. Paste a link and I'll handle everything.\" },\n    { icon:\"⚡\", title:\"Flash sale\",        sub:\"Drive sales right now\",                  prompt:\"Help me set up a flash sale on my best products today.\" },\n    { icon:\"📣\", title:\"Write ad copy\",     sub:\"TikTok · WhatsApp · Instagram\",          prompt:\"Write high-converting ad copy for my top product across TikTok, WhatsApp, and Instagram.\" },\n    { icon:\"🚀\", title:\"Growth plan\",       sub:\"Specific 5-step plan\",                   prompt:\"Give me a specific 5-step plan to grow my store revenue this month based on my current data.\" },\n  ];\n\n  return (\n    <div style={{ flex:1, display:\"flex\", flexDirection:\"column\", alignItems:\"center\", justifyContent:\"center\", padding:\"28px 20px 20px\", overflowY:\"auto\", minHeight:0 }}>\n\n      {/* Orb */}\n      <motion.div initial={{ opacity:0, scale:0.7 }} animate={{ opacity:1, scale:1 }}\n        transition={{ type:\"spring\", stiffness:200, damping:18 }}\n        style={{ marginBottom:22, position:\"relative\" }}>\n        <motion.div animate={{ scale:[1,1.08,1] }} transition={{ duration:3, repeat:Infinity, ease:\"easeInOut\" }}>\n          <KIROLogo size={64}/>\n        </motion.div>\n        <motion.div animate={{ rotate:360 }} transition={{ duration:7, repeat:Infinity, ease:\"linear\" }}\n          style={{ position:\"absolute\", inset:-8, borderRadius:\"50%\", border:`1px dashed ${ACCENT}30` }}>\n          <div style={{ position:\"absolute\", top:-3, left:\"50%\", width:7, height:7, borderRadius:\"50%\", background: ACCENT, boxShadow:`0 0 6px ${ACCENT}`, transform:\"translateX(-50%)\" }}/>\n        </motion.div>\n      </motion.div>\n\n      {/* Greeting */}\n      <motion.div initial={{ opacity:0, y:10 }} animate={{ opacity:1, y:0 }} transition={{ delay:0.1 }}\n        style={{ textAlign:\"center\", marginBottom:24 }}>\n        <h2 style={{ fontSize:22, fontWeight:700, color: t.text, margin:\"0 0 5px\", letterSpacing:\"-0.4px\" }}>\n          {greeting}\n        </h2>\n        <p style={{ fontSize:13, color: t.sub, margin:0 }}>Your commerce AI is ready.</p>\n      </motion.div>\n\n      {/* Store metrics */}\n      {storeData && (\n        <motion.div initial={{ opacity:0, y:8 }} animate={{ opacity:1, y:0 }} transition={{ delay:0.15 }}\n          style={{ display:\"flex\", gap:8, flexWrap:\"wrap\", justifyContent:\"center\", marginBottom:24 }}>\n          {[\n            { label:\"Today\", value: storeData.revenueToday > 0 ? `${sym}${storeData.revenueToday.toLocaleString()}` : `${sym}0`, alert: false },\n            { label:\"Pending\", value: String(storeData.pendingOrders||0), alert: storeData.pendingOrders > 0 },\n            { label:\"Health\",  value: storeData.healthScore ? `${storeData.healthScore}/100` : \"–\", alert: false },\n          ].map(m => (\n            <div key={m.label} style={{ padding:\"7px 14px\", borderRadius:9, background: t.surface, border:`1px solid ${m.alert ? t.amber+\"40\" : t.border}`, boxShadow: m.alert ? `0 0 10px ${t.amber}18` : \"none\" }}>\n              <p style={{ fontSize:13, fontWeight:700, color: m.alert ? t.amber : t.accent, margin:0 }}>{m.value}</p>\n              <p style={{ fontSize:9, color: t.muted, margin:0, textTransform:\"uppercase\", letterSpacing:\"0.08em\", fontWeight:600 }}>{m.label}</p>\n            </div>\n          ))}\n        </motion.div>\n      )}\n\n      {/* Quick actions */}\n      <motion.div initial={{ opacity:0 }} animate={{ opacity:1 }} transition={{ delay:0.2 }}\n        style={{ width:\"100%\", maxWidth:480 }}>\n        <div style={{ display:\"grid\", gridTemplateColumns:\"repeat(3,1fr)\", gap:8, marginBottom:12 }}>\n          {QUICK.map((q,i) => (\n            <motion.button key={q.title}\n              initial={{ opacity:0, y:8 }} animate={{ opacity:1, y:0 }} transition={{ delay:0.22+i*0.05 }}\n              whileHover={{ y:-2, transition:{ duration:0.12 } }} whileTap={{ scale:0.97 }}\n              onClick={() => onSend(q.prompt)}\n              style={{ padding:\"11px 10px\", borderRadius:11, border:`1px solid ${t.border}`, background: t.surface, cursor:\"pointer\", textAlign:\"left\", boxShadow: t.shadow }}>\n              <span style={{ fontSize:17, display:\"block\", marginBottom:4 }}>{q.icon}</span>\n              <span style={{ fontSize:11, fontWeight:600, color: t.text, display:\"block\", lineHeight:1.3 }}>{q.title}</span>\n              <span style={{ fontSize:10, color: t.sub, display:\"block\", lineHeight:1.4, marginTop:1 }}>{q.sub}</span>\n            </motion.button>\n          ))}\n        </div>\n      </motion.div>\n\n      {/* Pending orders urgent card */}\n      {storeData?.pendingOrders > 0 && (\n        <motion.button initial={{ opacity:0 }} animate={{ opacity:1 }} transition={{ delay:0.6 }}\n          whileHover={{ y:-1 }} whileTap={{ scale:0.98 }}\n          onClick={() => onSend(`Help me fulfill my ${storeData.pendingOrders} pending orders right now.`)}\n          style={{ width:\"100%\", maxWidth:480, padding:\"10px 14px\", borderRadius:10, border:`1px solid ${t.amber}35`, background:`${t.amber}0A`, cursor:\"pointer\", display:\"flex\", alignItems:\"center\", gap:10 }}>\n          <span style={{ fontSize:18 }}>📬</span>\n          <div style={{ flex:1, textAlign:\"left\" }}>\n            <p style={{ fontSize:13, fontWeight:600, color: t.amber, margin:0 }}>{storeData.pendingOrders} unfulfilled order{storeData.pendingOrders>1?\"s\":\"\"}</p>\n            <p style={{ fontSize:11, color:`${t.amber}90`, margin:0 }}>Customers are waiting — tap to act now</p>\n          </div>\n          <span style={{ color: t.amber, opacity:0.6 }}>→</span>\n        </motion.button>\n      )}\n\n      <p style={{ fontSize:11, color: t.muted, margin:\"14px 0 0\", textAlign:\"center\" }}>\n        Paste any product URL · Upload image or PDF · ⌘K\n      </p>\n    </div>\n  );\n}\n\n// ── Props ──────────────────────────────────────────────────────────────────────\ninterface KIROChatProps {\n  storeId?:               string;\n  conversationId?:        string;\n  briefMessage?:          string;\n  className?:             string;\n  onConversationCreated?: (id: string) => void;\n  onFirstMessage?:        (text: string) => void;\n}\n\n// ── Main component ─────────────────────────────────────────────────────────────\nexport default function KIROChat({ storeId: propStoreId, conversationId: initConvId, onConversationCreated, onFirstMessage }: KIROChatProps) {\n  const user    = useAuthStore(s => s.user);\n  const token   = useAuthStore(s => s.accessToken);\n  const storeId = propStoreId || user?.stores?.[0]?.id || \"\";\n\n  // ── state ──────────────────────────────────────────────────────────────────\n  const [mode,      setMode]      = useState<Mode>(\"light\");\n  const [messages,  setMessages]  = useState<Msg[]>([]);\n  const [input,     setInput]     = useState(\"\");\n  const [loading,   setLoading]   = useState(false);\n  const [convId,    setConvId]    = useState(initConvId || \"\");\n  const [storeData, setStoreData] = useState<any>(null);\n  const [attach,    setAttach]    = useState<any>(null);\n  const [uploading, setUploading] = useState(false);\n  const [listening, setListening] = useState(false);\n  const [voiceInterim, setVoiceInterim] = useState(\"\");\n  const [rateLimit, setRateLimit] = useState(false);\n\n  const bottomRef = useRef<HTMLDivElement>(null);\n  const inputRef  = useRef<HTMLTextAreaElement>(null);\n  const abortRef  = useRef<AbortController | null>(null);\n  const fileRef   = useRef<HTMLInputElement>(null);\n  const recogRef  = useRef<any>(null);\n\n  const t = T[mode];\n\n  // ── sync mode from localStorage ────────────────────────────────────────────\n  useEffect(() => {\n    const saved = localStorage.getItem(\"kiro-mode\") as Mode | null;\n    if (saved) setMode(saved);\n    const handler = () => { const m = localStorage.getItem(\"kiro-mode\") as Mode|null; if (m) setMode(m); };\n    window.addEventListener(\"storage\", handler);\n    return () => window.removeEventListener(\"storage\", handler);\n  }, []);\n\n  // ── auto scroll ────────────────────────────────────────────────────────────\n  useEffect(() => { bottomRef.current?.scrollIntoView({ behavior:\"smooth\" }); }, [messages]);\n\n  // ── load store greeting ────────────────────────────────────────────────────\n  useEffect(() => {\n    if (!storeId) return;\n    api.get(`/kai/greeting?storeId=${storeId}`)\n      .then(r => setStoreData(r.data?.data?.storeContext || r.data?.data))\n      .catch(() => {});\n  }, [storeId]);\n\n  // ── load conversation history ──────────────────────────────────────────────\n  useEffect(() => {\n    if (!initConvId) return;\n    api.get(`/kai/conversation/${initConvId}`)\n      .then(r => {\n        const msgs = (r.data?.data?.messages || []).map((m: any) => ({\n          id: m.id, role: m.role === \"user\" ? \"user\" : \"assistant\",\n          content: m.content, ts: m.createdAt, actions: m.actions || [],\n        }));\n        if (msgs.length) setMessages(msgs);\n      }).catch(() => {});\n  }, [initConvId]);\n\n  // ── voice ──────────────────────────────────────────────────────────────────\n  const handleVoice = () => {\n    const SR = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;\n    if (!SR) { toast.error(\"Voice works best in Chrome or Edge\"); return; }\n    if (listening) {\n      recogRef.current?.stop();\n      setListening(false);\n      setVoiceInterim(\"\");\n      return;\n    }\n    const r = new SR();\n    r.lang = \"en-NG\";\n    r.interimResults = true;\n    r.continuous = true;\n    r.onresult = (e: any) => {\n      let interim = \"\";\n      let final   = \"\";\n      for (let i = e.resultIndex; i < e.results.length; i++) {\n        const t = e.results[i][0].transcript;\n        if (e.results[i].isFinal) final += t;\n        else interim += t;\n      }\n      // Show live interim in the bubble\n      setVoiceInterim(interim);\n      // Append final text to input\n      if (final) setInput(prev => (prev ? prev + \" \" + final : final).trim());\n    };\n    r.onerror = (e: any) => {\n      if (e.error !== \"aborted\") toast.error(\"Voice error — try again\");\n      setListening(false);\n      setVoiceInterim(\"\");\n    };\n    r.onend = () => { setListening(false); setVoiceInterim(\"\"); };\n    r.start();\n    recogRef.current = r;\n    setListening(true);\n  };\n\n  // ── file upload ────────────────────────────────────────────────────────────\n  const handleFile = async (file: File) => {\n    if (file.size > 20 * 1024 * 1024) { toast.error(\"Max 20MB\"); return; }\n    setUploading(true);\n    try {\n      const dataUrl = await new Promise<string>((res, rej) => {\n        const r = new FileReader(); r.onload=()=>res(r.result as string); r.onerror=rej; r.readAsDataURL(file);\n      });\n      const isImage = file.type.startsWith(\"image/\");\n      const isPDF   = file.type === \"application/pdf\";\n      setAttach({ url: isImage ? dataUrl : undefined, base64: isPDF ? dataUrl.split(\",\")[1] : undefined, type: isImage ? \"image\" : isPDF ? \"pdf\" : \"csv\", name: file.name, size: file.size });\n    } catch { toast.error(\"Upload failed\"); } finally { setUploading(false); }\n  };\n\n  // ── image generation ───────────────────────────────────────────────────────\n  const generateImage = useCallback((prompt: string) => {\n    const kid = `k${Date.now()}`;\n    const clean = prompt.replace(/^(generate|create|make|draw)\\s+(a[n]?\\s+)?(image|photo|picture|visual)\\s+(of\\s+|for\\s+)?/i,\"\").trim();\n    const encoded = encodeURIComponent(`${clean}, product photography, clean background, professional, high quality`);\n    const url = `https://image.pollinations.ai/prompt/${encoded}?width=768&height=768&seed=${Math.random()*9999|0}&nologo=true&model=flux`;\n    setMessages(p => [...p, { id:kid, role:\"assistant\", content:`Generating image for \"${clean}\"…`, streaming:true, ts:new Date().toISOString() }]);\n    const img = new Image();\n    img.onload  = () => setMessages(p => p.map(m => m.id===kid ? { ...m, streaming:false, content:`Here's your image.`, imageUrl:url } : m));\n    img.onerror = () => setMessages(p => p.map(m => m.id===kid ? { ...m, streaming:false, content:\"Image generation unavailable. Try describing the product to me instead.\" } : m));\n    img.src = url;\n  }, []);\n\n  // ── send ───────────────────────────────────────────────────────────────────\n  const send = useCallback(async (override?: string) => {\n    const text = (override || input).trim();\n    if ((!text && !attach) || loading || !storeId) return;\n\n    // Image gen intercept\n    if (text && /^(generate|create|make|draw|show)\\s+(a[n]?\\s+)?(image|photo|picture|visual)/i.test(text) && !attach) {\n      setMessages(p => [...p, { id:`u${Date.now()}`, role:\"user\", content:text, ts:new Date().toISOString() }]);\n      if (!override) setInput(\"\");\n      generateImage(text);\n      return;\n    }\n\n    const userMsg: Msg = { id:`u${Date.now()}`, role:\"user\", content: text || (attach ? `📎 ${attach.name}` : \"\"), imageUrl: attach?.type===\"image\" ? attach.url : undefined, ts:new Date().toISOString() };\n    const kiroId = `k${Date.now()}`;\n    const kiroMsg: Msg = { id:kiroId, role:\"assistant\", content:\"\", streaming:true, ts:new Date().toISOString() };\n\n    // Fire onFirstMessage so parent can title the session properly\n    if (messages.length === 0 && onFirstMessage) {\n      onFirstMessage(text || (attach?.name ? `📎 ${attach.name}` : 'New conversation'));\n    }\n\n    setMessages(p => [...p, userMsg, kiroMsg]);\n    if (!override) setInput(\"\");\n    setAttach(null);\n    setLoading(true);\n\n    abortRef.current?.abort();\n    abortRef.current = new AbortController();\n\n    try {\n      const body: any = { message: text || \"\", storeId, conversationId: convId || undefined };\n      if (attach?.type === \"image\" && attach.url?.startsWith(\"data:\")) {\n        body.imageBase64    = attach.url.split(\",\")[1];\n        body.imageMediaType = attach.url.split(\":\")[1]?.split(\";\")[0] || \"image/jpeg\";\n        body.imageUrl       = attach.url;\n      } else if (attach?.url) body.imageUrl = attach.url;\n      if (attach?.base64) { body.fileBase64 = attach.base64; body.fileType = attach.type; }\n      if (attach?.name)   body.fileName = attach.name;\n\n      const res = await fetch(`${BASE}/kai/smart-chat`, {\n        method: \"POST\",\n        headers: { \"Content-Type\":\"application/json\", ...(token ? { Authorization:`Bearer ${token}` } : {}) },\n        body: JSON.stringify(body),\n        signal: abortRef.current.signal,\n      });\n\n      if (!res.ok) {\n        const d = await res.json().catch(()=>({}));\n        if (res.status === 429 || d?.code === \"RATE_LIMIT\") { setRateLimit(true); return; }\n        throw new Error(d?.message || \"Request failed\");\n      }\n\n      const reader = res.body!.getReader();\n      const dec = new TextDecoder();\n      let full = \"\";\n      let newConvId = \"\";\n\n      while (true) {\n        const { done, value } = await reader.read();\n        if (done) break;\n        for (const line of dec.decode(value,{stream:true}).split(\"\\n\").filter(l=>l.startsWith(\"data: \"))) {\n          try {\n            const p = JSON.parse(line.slice(6));\n            if (p.token) { full += p.token; setMessages(m => m.map(x => x.id===kiroId ? {...x,content:full} : x)); }\n            if (p.conversationId && !convId) newConvId = p.conversationId;\n            if (p.actions?.length) setMessages(m => m.map(x => x.id===kiroId ? {...x, actions:[...(x.actions||[]),...p.actions].filter((a,i,arr)=>arr.findIndex(b=>b.type===a.type)===i)} : x));\n            if (p.done) {\n              if (newConvId) { setConvId(newConvId); onConversationCreated?.(newConvId); }\n              // Parse any inline actions from text\n              const inlineActions = parseActions(full);\n              setMessages(m => m.map(x => x.id===kiroId ? {\n                ...x, streaming:false,\n                actions: [...(x.actions||[]), ...inlineActions].filter((a,i,arr)=>arr.findIndex(b=>b.type===a.type)===i),\n              } : x));\n            }\n          } catch {}\n        }\n      }\n    } catch (err: any) {\n      if (err.name === \"AbortError\") return;\n      setMessages(m => m.map(x => x.id===kiroId ? {...x, streaming:false, content:\"Something went wrong. Check your connection and try again.\" } : x));\n    } finally { setLoading(false); }\n  }, [input, attach, loading, storeId, convId, token, generateImage, onConversationCreated]);\n\n  // ── action handlers ────────────────────────────────────────────────────────\n  const handleApprove = async (action: Action) => {\n    try {\n      const r = await api.post(\"/kai/action\", { storeId, actions:[{...action,approved:true}] });\n      const result = r.data?.results?.[0];\n      if (result?.success) toast.success(result.message || \"Done!\");\n      else if (result?.healedAction) {\n        toast.loading(\"Auto-fixing…\", {id:\"heal\"});\n        const r2 = await api.post(\"/kai/action\",{storeId,actions:[{...result.healedAction,approved:true}]});\n        const r2res = r2.data?.results?.[0];\n        if (r2res?.success) toast.success(r2res.message||\"Fixed and done!\",{id:\"heal\"});\n        else toast.error(result?.message||\"Action failed\",{id:\"heal\"});\n      } else toast.error(result?.message||\"Action failed\");\n    } catch (e: any) { toast.error(e.response?.data?.message||\"Failed\"); }\n  };\n\n  const handleRate = (id: string, v: \"up\"|\"down\") => {\n    setMessages(m => m.map(x => x.id===id ? {...x,thumbs:v} : x));\n  };\n\n  const handleRegen = async (id: string) => {\n    const idx = messages.findIndex(m => m.id===id);\n    if (idx < 1) return;\n    const prev = messages.slice(0,idx).reverse().find(m=>m.role===\"user\");\n    if (prev) { setMessages(m=>m.filter((_,i)=>i<idx)); send(prev.content); }\n  };\n\n  // ── render ─────────────────────────────────────────────────────────────────\n  return (\n    <div style={{ display:\"flex\", flexDirection:\"column\", height:\"100%\", minHeight:0, background: t.bg, fontFamily:\"'Inter',system-ui,sans-serif\", overflow:\"hidden\" }}>\n      <style>{`\n        @import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700&display=swap');\n        @keyframes ks { to { transform: rotate(360deg); } }\n        @keyframes voiceBar { 0%,100%{transform:scaleY(1);opacity:.5} 50%{transform:scaleY(2);opacity:1} }\n        * { box-sizing: border-box; }\n        ::-webkit-scrollbar { width: 4px; }\n        ::-webkit-scrollbar-thumb { background: ${t.scrollbar}; border-radius: 2px; }\n      `}</style>\n\n      {/* Rate limit screen */}\n      {rateLimit ? (\n        <div style={{ flex:1, minHeight:0, display:\"flex\", flexDirection:\"column\", alignItems:\"center\", justifyContent:\"center\", padding:32, textAlign:\"center\" }}>\n          <div style={{ fontSize:48, marginBottom:16 }}>🔥</div>\n          <h2 style={{ fontSize:20, fontWeight:700, color:t.text, margin:\"0 0 8px\" }}>You've hit your limit</h2>\n          <p style={{ fontSize:14, color:t.sub, margin:\"0 0 20px\", maxWidth:280, lineHeight:1.6 }}>\n            Free accounts get 5 KIRO sessions per month. Upgrade to keep going.\n          </p>\n          <button onClick={()=>window.open(\"/dashboard/billing\",\"_blank\")}\n            style={{ padding:\"11px 24px\", borderRadius:10, border:\"none\", background:`linear-gradient(135deg,${t.accent},${t.accentD})`, color:\"#fff\", fontSize:14, fontWeight:600, cursor:\"pointer\" }}>\n            Unlock more sessions\n          </button>\n          <p style={{ fontSize:11, color:t.muted, margin:\"12px 0 0\" }}>Resets on the 1st of every month</p>\n        </div>\n      ) : (\n        <>\n          {/* Messages */}\n          <div style={{ flex:1, overflowY:\"auto\", padding:\"20px 16px\", minHeight:0, position:\"relative\" }}>\n            {messages.length === 0 ? (\n              <Welcome name={user?.name||\"there\"} storeData={storeData} onSend={send} t={t}/>\n            ) : (\n              messages.map(msg => (\n                <MsgBubble key={msg.id} msg={msg} onApprove={handleApprove}\n                  onDismiss={a=>setMessages(m=>m.map(x=>({...x,actions:(x.actions||[]).filter(b=>b!==a)})))}\n                  onRate={handleRate} onRegen={handleRegen} t={t}/>\n              ))\n            )}\n            <div ref={bottomRef}/>\n          </div>\n\n          {/* Stop bar */}\n          {loading && (\n            <div style={{ padding:\"8px 16px\", borderTop:`1px solid ${t.border}`, background:t.surface, display:\"flex\", alignItems:\"center\", gap:10, flexShrink:0 }}>\n              <Spinner size={14} color={t.accent}/>\n              <span style={{ fontSize:12, color:t.sub, flex:1 }}>KIRO is thinking</span>\n              <button onClick={()=>abortRef.current?.abort()}\n                style={{ padding:\"4px 12px\", borderRadius:7, border:`1px solid ${t.border}`, background:\"transparent\", color:t.red, fontSize:12, cursor:\"pointer\" }}>\n                ⏹ Stop\n              </button>\n            </div>\n          )}\n\n          {/* Attachment chip */}\n          <AnimatePresence>\n            {attach && (\n              <motion.div initial={{height:0,opacity:0}} animate={{height:\"auto\",opacity:1}} exit={{height:0,opacity:0}}\n                style={{ padding:\"6px 14px\", borderTop:`1px solid ${t.border}`, background:t.surface, display:\"flex\", alignItems:\"center\", gap:8, flexShrink:0 }}>\n                {attach.type===\"image\" && attach.url && (\n                  <img src={attach.url} alt=\"\" style={{ width:32, height:32, borderRadius:6, objectFit:\"cover\" }}/>\n                )}\n                {attach.type!==\"image\" && <span style={{ fontSize:18 }}>{attach.type===\"pdf\"?\"📄\":\"📊\"}</span>}\n                <span style={{ fontSize:12, color:t.sub, flex:1, overflow:\"hidden\", textOverflow:\"ellipsis\", whiteSpace:\"nowrap\" }}>{attach.name}</span>\n                <button onClick={()=>setAttach(null)} style={{ width:20, height:20, borderRadius:\"50%\", border:\"none\", background:t.elevated, color:t.sub, cursor:\"pointer\", fontSize:12, display:\"flex\", alignItems:\"center\", justifyContent:\"center\" }}>×</button>\n              </motion.div>\n            )}\n          </AnimatePresence>\n\n          {/* Input */}\n          <div style={{ padding:\"10px 14px 14px\", borderTop:`1px solid ${t.border}`, background:t.surface, flexShrink:0 }}>\n            <div style={{ borderRadius:14, border:`1px solid ${t.border}`, background:t.bg, overflow:\"hidden\", boxShadow:t.shadow, transition:\"border-color 0.15s, box-shadow 0.15s\" }}\n              onFocusCapture={e=>{(e.currentTarget as HTMLDivElement).style.borderColor=t.accent;(e.currentTarget as HTMLDivElement).style.boxShadow=`0 0 0 3px ${t.accentBg}`;}}\n              onBlurCapture={e=>{(e.currentTarget as HTMLDivElement).style.borderColor=t.border;(e.currentTarget as HTMLDivElement).style.boxShadow=t.shadow;}}>\n\n              <textarea ref={inputRef} value={input}\n                onChange={e=>{ setInput(e.target.value); e.target.style.height=\"auto\"; e.target.style.height=Math.min(e.target.scrollHeight,160)+\"px\"; }}\n                onKeyDown={e=>{ if(e.key===\"Enter\"&&!e.shiftKey){e.preventDefault();send();} }}\n                onPaste={e=>{ const f=e.clipboardData.files?.[0]; if(f){handleFile(f);} }}\n                placeholder=\"Message KIRO… paste a URL, describe a product, or ask anything\"\n                rows={1} style={{ width:\"100%\", background:\"transparent\", border:\"none\", outline:\"none\", color:t.text, fontSize:14, lineHeight:1.6, resize:\"none\", padding:\"12px 14px 4px\", maxHeight:160, overflowY:\"auto\" }}/>\n\n              {/* Toolbar row */}\n              <div style={{ display:\"flex\", alignItems:\"center\", gap:4, padding:\"4px 10px 8px\" }}>\n                {/* Image upload */}\n                <button onClick={()=>{ fileRef.current!.accept=\"image/*\"; fileRef.current?.click(); }} disabled={uploading} title=\"Upload image\"\n                  style={{ width:28, height:28, borderRadius:7, border:\"none\", background:\"transparent\", color:t.sub, cursor:\"pointer\", fontSize:15, display:\"flex\", alignItems:\"center\", justifyContent:\"center\" }}>\n                  {uploading ? <Spinner size={12} color={t.accent}/> : \"🖼\"}\n                </button>\n                {/* File upload */}\n                <button onClick={()=>{ fileRef.current!.accept=\"image/*,.pdf,.csv\"; fileRef.current?.click(); }} disabled={uploading} title=\"Attach file\"\n                  style={{ width:28, height:28, borderRadius:7, border:\"none\", background:\"transparent\", color:t.sub, cursor:\"pointer\", fontSize:15, display:\"flex\", alignItems:\"center\", justifyContent:\"center\" }}>\n                  📎\n                </button>\n                {/* Voice — animated bars + live transcript */}\n                <div style={{ position:\"relative\", display:\"flex\", alignItems:\"center\", gap:4 }}>\n                  {listening && voiceInterim && (\n                    <div style={{ position:\"absolute\", bottom:\"calc(100% + 8px)\", right:0, background:t.surface, border:`1px solid ${t.border}`, borderRadius:10, padding:\"7px 12px\", fontSize:12, color:t.text, whiteSpace:\"nowrap\", maxWidth:220, overflow:\"hidden\", textOverflow:\"ellipsis\", boxShadow:t.shadow, zIndex:20, pointerEvents:\"none\" }}>\n                      <span style={{ color:t.muted, fontSize:10, display:\"block\", marginBottom:2 }}>Listening…</span>\n                      {voiceInterim}\n                    </div>\n                  )}\n                  {listening && (\n                    <div style={{ display:\"flex\", alignItems:\"center\", gap:2 }}>\n                      {[0,1,2,3,4].map(i => (\n                        <div key={i} style={{ width:3, height:14, borderRadius:99, background:t.red, animation:`voiceBar 0.6s ease-in-out ${i*0.1}s infinite`, opacity:0.85 }}/>\n                      ))}\n                    </div>\n                  )}\n                  <button onClick={handleVoice} title={listening ? \"Stop recording\" : \"Voice input\"}\n                    style={{ width:30, height:30, borderRadius:8, border:`1px solid ${listening ? t.red : t.border}`, background:listening ? `${t.red}15` : \"transparent\", color:listening ? t.red : t.sub, cursor:\"pointer\", display:\"flex\", alignItems:\"center\", justifyContent:\"center\", transition:\"all 0.2s\", flexShrink:0 }}>\n                    {listening\n                      ? <svg width=\"11\" height=\"11\" viewBox=\"0 0 24 24\" fill=\"currentColor\"><rect x=\"4\" y=\"4\" width=\"16\" height=\"16\" rx=\"2\"/></svg>\n                      : <svg width=\"13\" height=\"13\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" strokeWidth=\"2\" strokeLinecap=\"round\"><path d=\"M12 1a3 3 0 0 0-3 3v8a3 3 0 0 0 6 0V4a3 3 0 0 0-3-3z\"/><path d=\"M19 10v2a7 7 0 0 1-14 0v-2\"/><line x1=\"12\" y1=\"19\" x2=\"12\" y2=\"23\"/><line x1=\"8\" y1=\"23\" x2=\"16\" y2=\"23\"/></svg>\n                    }\n                  </button>\n                </div>\n                {/* Generate image */}\n                <button onClick={()=>input.trim()?generateImage(input.trim()):toast.error(\"Describe what to generate\")} title=\"Generate AI image\"\n                  style={{ padding:\"3px 8px\", borderRadius:6, border:`1px solid ${t.border}`, background:\"transparent\", color:t.accent, cursor:\"pointer\", fontSize:11, fontWeight:600 }}>\n                  ✨ Image\n                </button>\n\n                <div style={{ flex:1 }}/>\n\n                {input.length > 300 && (\n                  <span style={{ fontSize:10, color:t.muted }}>{input.length}</span>\n                )}\n\n                {/* Send / stop */}\n                <motion.button onClick={()=>loading?abortRef.current?.abort():send()} whileTap={{scale:0.9}}\n                  style={{ width:32, height:32, borderRadius:9, border:\"none\", cursor:\"pointer\", display:\"flex\", alignItems:\"center\", justifyContent:\"center\", transition:\"all 0.18s\",\n                    background:loading?\"rgba(220,38,38,0.12)\":(input.trim()||attach)?`linear-gradient(135deg,${t.accent},${t.accentD})`:`${t.accent}18`,\n                    boxShadow:(input.trim()||attach)&&!loading?`0 2px 10px ${t.accent}35`:\"none\" }}>\n                  {loading\n                    ? <Spinner size={12} color={t.red}/>\n                    : <svg width={13} height={13} viewBox=\"0 0 24 24\" fill=\"none\"><path d=\"M22 2L11 13M22 2L15 22l-4-9-9-4 20-7z\" stroke={(input.trim()||attach)?\"#fff\":t.accent} strokeWidth={2} strokeLinecap=\"round\" strokeLinejoin=\"round\"/></svg>}\n                </motion.button>\n              </div>\n            </div>\n\n            <p style={{ fontSize:10, color:t.muted, textAlign:\"center\", margin:\"6px 0 0\" }}>\n              KIRO · Built by Darkweb & DropOS\n            </p>\n          </div>\n        </>\n      )}\n\n      <input ref={fileRef} type=\"file\" accept=\"image/*,.pdf,.csv\" style={{ display:\"none\" }}\n        onChange={e=>{ if(e.target.files?.[0]) handleFile(e.target.files[0]); e.target.value=\"\"; }}/>\n    </div>\n  );\n}\n",
};
for(const[rel,c]of Object.entries(files)){
  const p=rel.split('/').join(path.sep);
  fs.mkdirSync(path.dirname(p),{recursive:true});
  fs.writeFileSync(p,c,'utf8');
  console.log('OK',rel.split('/').pop());
}
console.log('Written 2 files');
try{
  execSync('git add .',{stdio:'inherit'});
  const st=execSync('git status --short',{encoding:'utf8'}).trim();
  if(st){
    execSync('git commit -m "fix: chat history titles show real first message, not generic label"',{stdio:'inherit'});
    execSync('git push origin main',{stdio:'inherit'});
    console.log('Pushed. Vercel deploying.');
  }else{console.log('Nothing new.');}
}catch(e){console.log('Git error:',e.message);}
